window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ZEP"]={"book":"ZEP","editions":{"hbo-source":[[1,1,"דְּבַר־יְהוָ֣ה ׀ אֲשֶׁ֣ר הָיָ֗ה אֶל־צְפַנְיָה֙ בֶּן־כּוּשִׁ֣י בֶן־גְּדַלְיָ֔ה בֶּן־אֲמַרְיָ֖ה בֶּן־חִזְקִיָּ֑ה בִּ⁠ימֵ֛י יֹאשִׁיָּ֥הוּ בֶן־אָמ֖וֹן מֶ֥לֶךְ יְהוּדָֽה׃","dĕ̇bar-yĕhwá֣h ׀ ʼàşě֣r háyá֗h ʼel-ẕĕpanĕyáh֙ bėn-k̇ẇşǐ֣y ben-gĕ̇dalĕyá֔h bėn-ʼàmarĕyá֖h bėn-ẖizĕqiyá֑̇h bi̇⁠ymé֛y yòʼşǐyá֥̇hẇ ben-ʼám֖wòn me֥lekĕ yĕhẇdáֽh׃"],[1,2,"אָסֹ֨ף אָסֵ֜ף כֹּ֗ל מֵ⁠עַ֛ל פְּנֵ֥י הָ⁠אֲדָמָ֖ה נְאֻם־יְהוָֽה׃","ʼásò֨p ʼásé֜p kò̇֗l mé⁠ʻa֛l pĕ̇né֥y há⁠ʼàdámá֖h nĕʼum-yĕhwáֽh׃"],[1,3,"אָסֵ֨ף אָדָ֜ם וּ⁠בְהֵמָ֗ה אָסֵ֤ף עוֹף־הַ⁠שָּׁמַ֨יִם֙ וּ⁠דְגֵ֣י הַ⁠יָּ֔ם וְ⁠הַ⁠מַּכְשֵׁל֖וֹת אֶת־הָ⁠רְשָׁעִ֑ים וְ⁠הִכְרַתִּ֣י אֶת־הָ⁠אָדָ֗ם מֵ⁠עַ֛ל פְּנֵ֥י הָ⁠אֲדָמָ֖ה נְאֻם־יְהוָֽה׃","ʼásé֨p ʼádá֜m ẇ⁠bĕhémá֗h ʼásé֤p ʻwòp-ha⁠şá̇̌ma֨yim֙ ẇ⁠dĕgé֣y ha⁠yá̇֔m wĕ⁠ha⁠mȧkĕşé̌l֖wòţ ʼeţ-há⁠rĕşá̌ʻi֑ym wĕ⁠hikĕraţi֣̇y ʼeţ-há⁠ʼádá֗m mé⁠ʻa֛l pĕ̇né֥y há⁠ʼàdámá֖h nĕʼum-yĕhwáֽh׃"],[1,4,"וְ⁠נָטִ֤יתִי יָדִ⁠י֙ עַל־יְהוּדָ֔ה וְ⁠עַ֖ל כָּל־יוֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם וְ⁠הִכְרַתִּ֞י מִן־הַ⁠מָּק֤וֹם הַ⁠זֶּה֙ אֶת־שְׁאָ֣ר הַ⁠בַּ֔עַל אֶת־שֵׁ֥ם הַ⁠כְּמָרִ֖ים עִם־הַ⁠כֹּהֲנִֽים׃","wĕ⁠náti֤yţiy yádi⁠y֙ ʻal-yĕhẇdá֔h wĕ⁠ʻa֖l ká̇l-ywòşĕ̌bé֣y yĕrẇşá̌liá֑m wĕ⁠hikĕraţi̇֞y min-ha⁠má̇q֤wòm ha⁠zėh֙ ʼeţ-şĕ̌ʼá֣r ha⁠bȧ֔ʻal ʼeţ-şé֥̌m ha⁠kĕ̇mári֖ym ʻim-ha⁠kò̇hàniֽym׃"],[1,5,"וְ⁠אֶת־הַ⁠מִּשְׁתַּחֲוִ֥ים עַל־הַ⁠גַּגּ֖וֹת לִ⁠צְבָ֣א הַ⁠שָּׁמָ֑יִם וְ⁠אֶת־הַ⁠מִּֽשְׁתַּחֲוִים֙ הַ⁠נִּשְׁבָּעִ֣ים לַֽ⁠יהוָ֔ה וְ⁠הַ⁠נִּשְׁבָּעִ֖ים בְּ⁠מַלְכָּֽ⁠ם׃","wĕ⁠ʼeţ-ha⁠mi̇şĕ̌ţȧẖàwi֥ym ʻal-ha⁠gȧġ֖wòţ li⁠ẕĕbá֣ʼ ha⁠şá̇̌má֑yim wĕ⁠ʼeţ-ha⁠miֽ̇şĕ̌ţȧẖàwiym֙ ha⁠ni̇şĕ̌bá̇ʻi֣ym laֽ⁠yhwá֔h wĕ⁠ha⁠ni̇şĕ̌bá̇ʻi֖ym bĕ̇⁠malĕkáֽ̇⁠m׃"],[1,6,"וְ⁠אֶת־הַ⁠נְּסוֹגִ֖ים מֵ⁠אַחֲרֵ֣י יְהוָ֑ה וַ⁠אֲשֶׁ֛ר לֹֽא־בִקְשׁ֥וּ אֶת־יְהוָ֖ה וְ⁠לֹ֥א דְרָשֻֽׁ⁠הוּ׃","wĕ⁠ʼeţ-ha⁠nĕ̇swògi֖ym mé⁠ʼaẖàré֣y yĕhwá֑h wa⁠ʼàşě֛r lòֽʼ-biqĕş֥̌ẇ ʼeţ-yĕhwá֖h wĕ⁠lò֥ʼ dĕráşǔֽ⁠hẇ׃"],[1,7,"הַ֕ס מִ⁠פְּנֵ֖י אֲדֹנָ֣⁠י יְהוִ֑ה כִּ֤י קָרוֹב֙ י֣וֹם יְהוָ֔ה כִּֽי־הֵכִ֧ין יְהוָ֛ה זֶ֖בַח הִקְדִּ֥ישׁ קְרֻאָֽי⁠ו׃","ha֕s mi⁠pĕ̇né֖y ʼàdòná֣⁠y yĕhwi֑h ki֤̇y qárwòb֙ y֣wòm yĕhwá֔h kiֽ̇y-héki֧yn yĕhwá֛h ze֖baẖ hiqĕdi֥̇yş̌ qĕruʼáֽy⁠w׃"],[1,8,"וְ⁠הָיָ֗ה בְּ⁠יוֹם֙ זֶ֣בַח יְהוָ֔ה וּ⁠פָקַדְתִּ֥י עַל־הַ⁠שָּׂרִ֖ים וְ⁠עַל־בְּנֵ֣י הַ⁠מֶּ֑לֶךְ וְ⁠עַ֥ל כָּל־הַ⁠לֹּבְשִׁ֖ים מַלְבּ֥וּשׁ נָכְרִֽי׃","wĕ⁠háyá֗h bĕ̇⁠ywòm֙ ze֣baẖ yĕhwá֔h ẇ⁠páqadĕţi֥̇y ʻal-ha⁠şá̇̂ri֖ym wĕ⁠ʻal-bĕ̇né֣y ha⁠mė֑lekĕ wĕ⁠ʻa֥l ká̇l-ha⁠lò̇bĕşǐ֖ym malĕḃ֥ẇş̌ nákĕriֽy׃"],[1,9,"וּ⁠פָקַדְתִּ֗י עַ֧ל כָּל־הַ⁠דּוֹלֵ֛ג עַל־הַ⁠מִּפְתָּ֖ן בַּ⁠יּ֣וֹם הַ⁠ה֑וּא הַֽ⁠מְמַלְאִ֛ים בֵּ֥ית אֲדֹנֵי⁠הֶ֖ם חָמָ֥ס וּ⁠מִרְמָֽה׃ס","ẇ⁠páqadĕţi̇֗y ʻa֧l ká̇l-ha⁠ḋwòlé֛g ʻal-ha⁠mi̇pĕţá֖̇n bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ haֽ⁠mĕmalĕʼi֛ym bé֥̇yţ ʼàdònéy⁠he֖m ẖámá֥s ẇ⁠mirĕmáֽh׃s"],[1,10,"וְ⁠הָיָה֩ בַ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻם־יְהוָ֗ה ק֤וֹל צְעָקָה֙ מִ⁠שַּׁ֣עַר הַ⁠דָּגִ֔ים וִֽ⁠ילָלָ֖ה מִן־הַ⁠מִּשְׁנֶ֑ה וְ⁠שֶׁ֥בֶר גָּד֖וֹל מֵ⁠הַ⁠גְּבָעֽוֹת׃","wĕ⁠háyáh֩ ba⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼum-yĕhwá֗h q֤wòl ẕĕʻáqáh֙ mi⁠şȧ֣̌ʻar ha⁠dá̇gi֔ym wiֽ⁠ylálá֖h min-ha⁠mi̇şĕ̌ne֑h wĕ⁠şě֥ber gá̇d֖wòl mé⁠ha⁠gĕ̇báʻֽwòţ׃"],[1,11,"הֵילִ֖ילוּ יֹשְׁבֵ֣י הַ⁠מַּכְתֵּ֑שׁ כִּ֤י נִדְמָה֙ כָּל־עַ֣ם כְּנַ֔עַן נִכְרְת֖וּ כָּל־נְטִ֥ילֵי כָֽסֶף׃","héyli֖ylẇ yòşĕ̌bé֣y ha⁠mȧkĕţé֑̇ş̌ ki֤̇y nidĕmáh֙ ká̇l-ʻa֣m kĕ̇na֔ʻan nikĕrĕţ֖ẇ ká̇l-nĕti֥yléy káֽsep׃"],[1,12,"וְ⁠הָיָה֙ בָּ⁠עֵ֣ת הַ⁠הִ֔יא אֲחַפֵּ֥שׂ אֶת־יְרוּשָׁלִַ֖ם בַּ⁠נֵּר֑וֹת וּ⁠פָקַדְתִּ֣י עַל־הָ⁠אֲנָשִׁ֗ים הַ⁠קֹּֽפְאִים֙ עַל־שִׁמְרֵי⁠הֶ֔ם הָ⁠אֹֽמְרִים֙ בִּ⁠לְבָבָ֔⁠ם לֹֽא־יֵיטִ֥יב יְהוָ֖ה וְ⁠לֹ֥א יָרֵֽעַ׃","wĕ⁠háyáh֙ bá̇⁠ʻé֣ţ ha⁠hi֔yʼ ʼàẖapé֥̇ş̂ ʼeţ-yĕrẇşá̌lia֖m bȧ⁠né̇r֑wòţ ẇ⁠páqadĕţi֣̇y ʻal-há⁠ʼànáşǐ֗ym ha⁠qòֽ̇pĕʼiym֙ ʻal-şǐmĕréy⁠he֔m há⁠ʼòֽmĕriym֙ bi̇⁠lĕbábá֔⁠m lòֽʼ-yéyti֥yb yĕhwá֖h wĕ⁠lò֥ʼ yáréֽʻa׃"],[1,13,"וְ⁠הָיָ֤ה חֵילָ⁠ם֙ לִ⁠מְשִׁסָּ֔ה וּ⁠בָתֵּי⁠הֶ֖ם לִ⁠שְׁמָמָ֑ה וּ⁠בָנ֤וּ בָתִּים֙ וְ⁠לֹ֣א יֵשֵׁ֔בוּ וְ⁠נָטְע֣וּ כְרָמִ֔ים וְ⁠לֹ֥א יִשְׁתּ֖וּ אֶת־יֵינָֽ⁠ם׃","wĕ⁠háyá֤h ẖéylá⁠m֙ li⁠mĕşǐsá̇֔h ẇ⁠báţé̇y⁠he֖m li⁠şĕ̌mámá֑h ẇ⁠bán֤ẇ báţi̇ym֙ wĕ⁠lò֣ʼ yéşé̌֔bẇ wĕ⁠nátĕʻ֣ẇ kĕrámi֔ym wĕ⁠lò֥ʼ yişĕ̌ţ֖̇ẇ ʼeţ-yéynáֽ⁠m׃"],[1,14,"קָר֤וֹב יוֹם־יְהוָה֙ הַ⁠גָּד֔וֹל קָר֖וֹב וּ⁠מַהֵ֣ר מְאֹ֑ד ק֚וֹל י֣וֹם יְהוָ֔ה מַ֥ר צֹרֵ֖חַ שָׁ֥ם גִּבּֽוֹר׃","qár֤wòb ywòm-yĕhwáh֙ ha⁠gá̇d֔wòl qár֖wòb ẇ⁠mahé֣r mĕʼò֑d q֚wòl y֣wòm yĕhwá֔h ma֥r ẕòré֖ẖa şá֥̌m gi̇ḃֽwòr׃"],[1,15,"י֥וֹם עֶבְרָ֖ה הַ⁠יּ֣וֹם הַ⁠ה֑וּא י֧וֹם צָרָ֣ה וּ⁠מְצוּקָ֗ה י֤וֹם שֹׁאָה֙ וּ⁠מְשׁוֹאָ֔ה י֥וֹם חֹ֨שֶׁךְ֙ וַ⁠אֲפֵלָ֔ה י֥וֹם עָנָ֖ן וַ⁠עֲרָפֶֽל׃","y֥wòm ʻebĕrá֖h ha⁠ẏ֣wòm ha⁠h֑ẇʼ y֧wòm ẕárá֣h ẇ⁠mĕẕẇqá֗h y֤wòm şò̌ʼáh֙ ẇ⁠mĕş̌wòʼá֔h y֥wòm ẖò֨şěkĕ֙ wa⁠ʼàpélá֔h y֥wòm ʻáná֖n wa⁠ʻàrápeֽl׃"],[1,16,"י֥וֹם שׁוֹפָ֖ר וּ⁠תְרוּעָ֑ה עַ֚ל הֶ⁠עָרִ֣ים הַ⁠בְּצֻר֔וֹת וְ⁠עַ֖ל הַ⁠פִּנּ֥וֹת הַ⁠גְּבֹהֽוֹת׃","y֥wòm ş̌wòpá֖r ẇ⁠ţĕrẇʻá֑h ʻa֚l he⁠ʻári֣ym ha⁠bĕ̇ẕur֔wòţ wĕ⁠ʻa֖l ha⁠pi̇ṅ֥wòţ ha⁠gĕ̇bòhֽwòţ׃"],[1,17,"וַ⁠הֲצֵרֹ֣תִי לָ⁠אָדָ֗ם וְ⁠הָֽלְכוּ֙ כַּֽ⁠עִוְרִ֔ים כִּ֥י לַֽ⁠יהוָ֖ה חָטָ֑אוּ וְ⁠שֻׁפַּ֤ךְ דָּמָ⁠ם֙ כֶּֽ⁠עָפָ֔ר וּ⁠לְחֻמָ֖⁠ם כַּ⁠גְּלָלִֽים׃","wa⁠hàẕérò֣ţiy lá⁠ʼádá֗m wĕ⁠háֽlĕkẇ֙ kȧֽ⁠ʻiwĕri֔ym ki֥̇y laֽ⁠yhwá֖h ẖátá֑ʼẇ wĕ⁠şǔpȧ֤kĕ dá̇má⁠m֙ kėֽ⁠ʻápá֔r ẇ⁠lĕẖumá֖⁠m kȧ⁠gĕ̇láliֽym׃"],[1,18,"גַּם־כַּסְפָּ֨⁠ם גַּם־זְהָבָ֜⁠ם לֹֽא־יוּכַ֣ל לְ⁠הַצִּילָ֗⁠ם בְּ⁠יוֹם֙ עֶבְרַ֣ת יְהוָ֔ה וּ⁠בְ⁠אֵשׁ֙ קִנְאָת֔⁠וֹ תֵּאָכֵ֖ל כָּל־הָ⁠אָ֑רֶץ כִּֽי־כָלָ֤ה אַךְ־נִבְהָלָה֙ יַֽעֲשֶׂ֔ה אֵ֥ת כָּל־יֹשְׁבֵ֖י הָ⁠אָֽרֶץ׃ס","gȧm-kȧsĕpá̇֨⁠m gȧm-zĕhábá֜⁠m lòֽʼ-yẇka֣l lĕ⁠haẕi̇ylá֗⁠m bĕ̇⁠ywòm֙ ʻebĕra֣ţ yĕhwá֔h ẇ⁠bĕ⁠ʼéş̌֙ qinĕʼáţ֔⁠wò ţé̇ʼáké֖l ká̇l-há⁠ʼá֑reẕ kiֽ̇y-kálá֤h ʼakĕ-nibĕháláh֙ yaֽʻàşê֔h ʼé֥ţ ká̇l-yòşĕ̌bé֖y há⁠ʼáֽreẕ׃s"],[2,1,"הִֽתְקוֹשְׁשׁ֖וּ וָ⁠ק֑וֹשּׁוּ הַ⁠גּ֖וֹי לֹ֥א נִכְסָֽף׃","hiֽţĕqwòşĕ̌ş֖̌ẇ wá⁠q֑wòş̇̌ẇ ha⁠ġ֖wòy lò֥ʼ nikĕsáֽp׃"],[2,2,"בְּ⁠טֶ֨רֶם֙ לֶ֣דֶת חֹ֔ק כְּ⁠מֹ֖ץ עָ֣בַר י֑וֹם בְּ⁠טֶ֣רֶם ׀ לֹא־יָב֣וֹא עֲלֵי⁠כֶ֗ם חֲרוֹן֙ אַף־יְהוָ֔ה בְּ⁠טֶ֨רֶם֙ לֹא־יָב֣וֹא עֲלֵי⁠כֶ֔ם י֖וֹם אַף־יְהוָֽה׃","bĕ̇⁠te֨rem֙ le֣deţ ẖò֔q kĕ̇⁠mò֖ẕ ʻá֣bar y֑wòm bĕ̇⁠te֣rem ׀ lòʼ-yáb֣wòʼ ʻàléy⁠ke֗m ẖàrwòn֙ ʼap-yĕhwá֔h bĕ̇⁠te֨rem֙ lòʼ-yáb֣wòʼ ʻàléy⁠ke֔m y֖wòm ʼap-yĕhwáֽh׃"],[2,3,"בַּקְּשׁ֤וּ אֶת־יְהוָה֙ כָּל־עַנְוֵ֣י הָ⁠אָ֔רֶץ אֲשֶׁ֥ר מִשְׁפָּט֖⁠וֹ פָּעָ֑לוּ בַּקְּשׁוּ־צֶ֨דֶק֙ בַּקְּשׁ֣וּ עֲנָוָ֔ה אוּלַי֙ תִּסָּ֣תְר֔וּ בְּ⁠י֖וֹם אַף־יְהוָֽה׃","bȧqĕ̇ş֤̌ẇ ʼeţ-yĕhwáh֙ ká̇l-ʻanĕwé֣y há⁠ʼá֔reẕ ʼàşě֥r mişĕ̌pá̇t֖⁠wò pá̇ʻá֑lẇ bȧqĕ̇ş̌ẇ-ẕe֨deq֙ bȧqĕ̇ş֣̌ẇ ʻànáwá֔h ʼẇlay֙ ţi̇sá֣̇ţĕr֔ẇ bĕ̇⁠y֖wòm ʼap-yĕhwáֽh׃"],[2,4,"כִּ֤י עַזָּה֙ עֲזוּבָ֣ה תִֽהְיֶ֔ה וְ⁠אַשְׁקְל֖וֹן לִ⁠שְׁמָמָ֑ה אַשְׁדּ֗וֹד בַּֽ⁠צָּהֳרַ֨יִם֙ יְגָ֣רְשׁ֔וּ⁠הָ וְ⁠עֶקְר֖וֹן תֵּעָקֵֽר׃ס","ki֤̇y ʻazá̇h֙ ʻàzẇbá֣h ţiֽhĕye֔h wĕ⁠ʼaşĕ̌qĕl֖wòn li⁠şĕ̌mámá֑h ʼaşĕ̌ḋ֗wòd bȧֽ⁠ẕá̇hora֨yim֙ yĕgá֣rĕş̌֔ẇ⁠há wĕ⁠ʻeqĕr֖wòn ţé̇ʻáqéֽr׃s"],[2,5,"ה֗וֹי יֹֽשְׁבֵ֛י חֶ֥בֶל הַ⁠יָּ֖ם גּ֣וֹי כְּרֵתִ֑ים דְּבַר־יְהוָ֣ה עֲלֵי⁠כֶ֗ם כְּנַ֨עַן֙ אֶ֣רֶץ פְּלִשְׁתִּ֔ים וְ⁠הַאֲבַדְתִּ֖י⁠ךְ מֵ⁠אֵ֥ין יוֹשֵֽׁב׃","h֗wòy yòֽşĕ̌bé֛y ẖe֥bel ha⁠yá֖̇m ġ֣wòy kĕ̇réţi֑ym dĕ̇bar-yĕhwá֣h ʻàléy⁠ke֗m kĕ̇na֨ʻan֙ ʼe֣reẕ pĕ̇lişĕ̌ţi̇֔ym wĕ⁠haʼàbadĕţi֖̇y⁠kĕ mé⁠ʼé֥yn ywòşéֽ̌b׃"],[2,6,"וְֽ⁠הָיְתָ֞ה חֶ֣בֶל הַ⁠יָּ֗ם נְוֺ֛ת כְּרֹ֥ת רֹעִ֖ים וְ⁠גִדְר֥וֹת צֹֽאן׃","wĕֽ⁠háyĕţá֞h ẖe֣bel ha⁠yá̇֗m nĕwֺ֛ţ kĕ̇rò֥ţ ròʻi֖ym wĕ⁠gidĕr֥wòţ ẕòֽʼn׃"],[2,7,"וְ⁠הָ֣יָה חֶ֗בֶל לִ⁠שְׁאֵרִ֛ית בֵּ֥ית יְהוּדָ֖ה עֲלֵי⁠הֶ֣ם יִרְע֑וּ⁠ן בְּ⁠בָתֵּ֣י אַשְׁקְל֗וֹן בָּ⁠עֶ֨רֶב֙ יִרְבָּצ֔וּ⁠ן כִּ֧י יִפְקְדֵ֛⁠ם יְהוָ֥ה אֱלֹהֵי⁠הֶ֖ם וְ⁠שָׁ֥ב שבות⁠ם׃","wĕ⁠há֣yáh ẖe֗bel li⁠şĕ̌ʼéri֛yţ bé֥̇yţ yĕhẇdá֖h ʻàléy⁠he֣m yirĕʻ֑ẇ⁠n bĕ̇⁠báţé֣̇y ʼaşĕ̌qĕl֗wòn bá̇⁠ʻe֨reb֙ yirĕbá̇ẕ֔ẇ⁠n ki֧̇y yipĕqĕdé֛⁠m yĕhwá֥h ʼèlòhéy⁠he֖m wĕ⁠şá֥̌b şbwţ⁠m׃"],[2,8,"שָׁמַ֨עְתִּי֙ חֶרְפַּ֣ת מוֹאָ֔ב וְ⁠גִדּוּפֵ֖י בְּנֵ֣י עַמּ֑וֹן אֲשֶׁ֤ר חֵֽרְפוּ֙ אֶת־עַמִּ֔⁠י וַ⁠יַּגְדִּ֖ילוּ עַל־גְּבוּלָֽ⁠ם׃","şá̌ma֨ʻĕţi̇y֙ ẖerĕpȧ֣ţ mwòʼá֔b wĕ⁠giḋẇpé֖y bĕ̇né֣y ʻaṁ֑wòn ʼàşě֤r ẖéֽrĕpẇ֙ ʼeţ-ʻami̇֔⁠y wa⁠yȧgĕdi֖̇ylẇ ʻal-gĕ̇bẇláֽ⁠m׃"],[2,9,"לָ⁠כֵ֣ן חַי־אָ֡נִי נְאֻם֩ יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֣י יִשְׂרָאֵ֗ל כִּֽי־מוֹאָ֞ב כִּ⁠סְדֹ֤ם תִּֽהְיֶה֙ וּ⁠בְנֵ֤י עַמּוֹן֙ כַּֽ⁠עֲמֹרָ֔ה מִמְשַׁ֥ק חָר֛וּל וּ⁠מִכְרֵה־מֶ֥לַח וּ⁠שְׁמָמָ֖ה עַד־עוֹלָ֑ם שְׁאֵרִ֤ית עַמִּ⁠י֙ יְבָזּ֔וּ⁠ם וְ⁠יֶ֥תֶר גוי יִנְחָלֽוּ⁠ם׃","lá⁠ké֣n ẖay-ʼá֡niy nĕʼum֩ yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֣y yişĕ̂ráʼé֗l kiֽ̇y-mwòʼá֞b ki̇⁠sĕdò֤m ţiֽ̇hĕyeh֙ ẇ⁠bĕné֤y ʻaṁwòn֙ kȧֽ⁠ʻàmòrá֔h mimĕşǎ֥q ẖár֛ẇl ẇ⁠mikĕréh-me֥laẖ ẇ⁠şĕ̌mámá֖h ʻad-ʻwòlá֑m şĕ̌ʼéri֤yţ ʻami̇⁠y֙ yĕbáż֔ẇ⁠m wĕ⁠ye֥ţer gwy yinĕẖálֽẇ⁠m׃"],[2,10,"זֹ֥את לָ⁠הֶ֖ם תַּ֣חַת גְּאוֹנָ֑⁠ם כִּ֤י חֵֽרְפוּ֙ וַ⁠יַּגְדִּ֔לוּ עַל־עַ֖ם יְהוָ֥ה צְבָאֽוֹת׃","zò֥ʼţ lá⁠he֖m ţȧ֣ẖaţ gĕ̇ʼwòná֑⁠m ki֤̇y ẖéֽrĕpẇ֙ wa⁠yȧgĕdi̇֔lẇ ʻal-ʻa֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[2,11,"נוֹרָ֤א יְהוָה֙ עֲלֵי⁠הֶ֔ם כִּ֣י רָזָ֔ה אֵ֖ת כָּל־אֱלֹהֵ֣י הָ⁠אָ֑רֶץ וְ⁠יִשְׁתַּֽחֲווּ־ל⁠וֹ֙ אִ֣ישׁ מִ⁠מְּקוֹמ֔⁠וֹ כֹּ֖ל אִיֵּ֥י הַ⁠גּוֹיִֽם׃","nwòrá֤ʼ yĕhwáh֙ ʻàléy⁠he֔m ki֣̇y rázá֔h ʼé֖ţ ká̇l-ʼèlòhé֣y há⁠ʼá֑reẕ wĕ⁠yişĕ̌ţȧֽẖàwẇ-l⁠wò֙ ʼi֣yş̌ mi⁠mĕ̇qwòm֔⁠wò kò֖̇l ʼiyé֥̇y ha⁠ġwòyiֽm׃"],[2,12,"גַּם־אַתֶּ֣ם כּוּשִׁ֔ים חַֽלְלֵ֥י חַרְבִּ֖⁠י הֵֽמָּה׃","gȧm-ʼaţė֣m k̇ẇşǐ֔ym ẖaֽlĕlé֥y ẖarĕbi֖̇⁠y héֽmá̇h׃"],[2,13,"וְ⁠יֵ֤ט יָד⁠וֹ֙ עַל־צָפ֔וֹן וִֽ⁠יאַבֵּ֖ד אֶת־אַשּׁ֑וּר וְ⁠יָשֵׂ֤ם אֶת־נִֽינְוֵה֙ לִ⁠שְׁמָמָ֔ה צִיָּ֖ה כַּ⁠מִּדְבָּֽר׃","wĕ⁠yé֤t yád⁠wò֙ ʻal-ẕáp֔wòn wiֽ⁠yʼabé֖̇d ʼeţ-ʼaş֑̇̌ẇr wĕ⁠yáşé֤̂m ʼeţ-niֽynĕwéh֙ li⁠şĕ̌mámá֔h ẕiyá֖̇h kȧ⁠mi̇dĕbáֽ̇r׃"],[2,14,"וְ⁠רָבְצ֨וּ בְ⁠תוֹכָ֤⁠הּ עֲדָרִים֙ כָּל־חַיְת⁠וֹ־ג֔וֹי גַּם־קָאַת֙ גַּם־קִפֹּ֔ד בְּ⁠כַפְתֹּרֶ֖י⁠הָ יָלִ֑ינוּ ק֠וֹל יְשׁוֹרֵ֤ר בַּֽ⁠חַלּוֹן֙ חֹ֣רֶב בַּ⁠סַּ֔ף כִּ֥י אַרְזָ֖ה עֵרָֽה׃","wĕ⁠rábĕẕ֨ẇ bĕ⁠ţwòká֤⁠ḣ ʻàdáriym֙ ká̇l-ẖayĕţ⁠wò-g֔wòy gȧm-qáʼaţ֙ gȧm-qipò̇֔d bĕ̇⁠kapĕţò̇re֖y⁠há yáli֑ynẇ q֠wòl yĕş̌wòré֤r bȧֽ⁠ẖal̇wòn֙ ẖò֣reb bȧ⁠sȧ֔p ki֥̇y ʼarĕzá֖h ʻéráֽh׃"],[2,15,"זֹ֞֠את הָ⁠עִ֤יר הָ⁠עַלִּיזָה֙ הַ⁠יּוֹשֶׁ֣בֶת לָ⁠בֶ֔טַח הָ⁠אֹֽמְרָה֙ בִּ⁠לְבָבָ֔⁠הּ אֲנִ֖י וְ⁠אַפְסִ֣⁠י ע֑וֹד אֵ֣יךְ ׀ הָיְתָ֣ה לְ⁠שַׁמָּ֗ה מַרְבֵּץ֙ לַֽ⁠חַיָּ֔ה כֹּ֚ל עוֹבֵ֣ר עָלֶ֔י⁠הָ יִשְׁרֹ֖ק יָנִ֥יעַ יָדֽ⁠וֹ׃ס","zò֞֠ʼţ há⁠ʻi֤yr há⁠ʻali̇yzáh֙ ha⁠ẏwòşě֣beţ lá⁠be֔taẖ há⁠ʼòֽmĕráh֙ bi̇⁠lĕbábá֔⁠ḣ ʼàni֖y wĕ⁠ʼapĕsi֣⁠y ʻ֑wòd ʼé֣ykĕ ׀ háyĕţá֣h lĕ⁠şǎmá̇֗h marĕbé̇ẕ֙ laֽ⁠ẖayá̇֔h kò֚̇l ʻwòbé֣r ʻále֔y⁠há yişĕ̌rò֖q yáni֥yʻa yádֽ⁠wò׃s"],[3,1,"ה֥וֹי מֹרְאָ֖ה וְ⁠נִגְאָלָ֑ה הָ⁠עִ֖יר הַ⁠יּוֹנָֽה׃","h֥wòy mòrĕʼá֖h wĕ⁠nigĕʼálá֑h há⁠ʻi֖yr ha⁠ẏwònáֽh׃"],[3,2,"לֹ֤א שָֽׁמְעָה֙ בְּ⁠ק֔וֹל לֹ֥א לָקְחָ֖ה מוּסָ֑ר בַּֽ⁠יהוָה֙ לֹ֣א בָטָ֔חָה אֶל־אֱלֹהֶ֖י⁠הָ לֹ֥א קָרֵֽבָה׃","lò֤ʼ şáֽ̌mĕʻáh֙ bĕ̇⁠q֔wòl lò֥ʼ láqĕẖá֖h mẇsá֑r bȧֽ⁠yhwáh֙ lò֣ʼ bátá֔ẖáh ʼel-ʼèlòhe֖y⁠há lò֥ʼ qáréֽbáh׃"],[3,3,"שָׂרֶ֣י⁠הָ בְ⁠קִרְבָּ֔⁠הּ אֲרָי֖וֹת שֹֽׁאֲגִ֑ים שֹׁפְטֶ֨י⁠הָ֙ זְאֵ֣בֵי עֶ֔רֶב לֹ֥א גָרְמ֖וּ לַ⁠בֹּֽקֶר׃","şá̂re֣y⁠há bĕ⁠qirĕbá̇֔⁠ḣ ʼàráy֖wòţ şòֽ̌ʼàgi֑ym şò̌pĕte֨y⁠há֙ zĕʼé֣béy ʻe֔reb lò֥ʼ gárĕm֖ẇ la⁠bòֽ̇qer׃"],[3,4,"נְבִיאֶ֨י⁠הָ֙ פֹּֽחֲזִ֔ים אַנְשֵׁ֖י בֹּֽגְד֑וֹת כֹּהֲנֶ֨י⁠הָ֙ חִלְּלוּ־קֹ֔דֶשׁ חָמְס֖וּ תּוֹרָֽה׃","nĕbiyʼe֨y⁠há֙ pòֽ̇ẖàzi֔ym ʼanĕşé֖̌y bòֽ̇gĕd֑wòţ kò̇hàne֨y⁠há֙ ẖilĕ̇lẇ-qò֔deş̌ ẖámĕs֖ẇ ţ̇wòráֽh׃"],[3,5,"יְהוָ֤ה צַדִּיק֙ בְּ⁠קִרְבָּ֔⁠הּ לֹ֥א יַעֲשֶׂ֖ה עַוְלָ֑ה בַּ⁠בֹּ֨קֶר בַּ⁠בֹּ֜קֶר מִשְׁפָּט֨⁠וֹ יִתֵּ֤ן לָ⁠אוֹר֙ לֹ֣א נֶעְדָּ֔ר וְ⁠לֹֽא־יוֹדֵ֥עַ עַוָּ֖ל בֹּֽשֶׁת׃","yĕhwá֤h ẕadi̇yq֙ bĕ̇⁠qirĕbá̇֔⁠ḣ lò֥ʼ yaʻàşê֖h ʻawĕlá֑h bȧ⁠bò̇֨qer bȧ⁠bò̇֜qer mişĕ̌pá̇t֨⁠wò yiţé֤̇n lá⁠ʼwòr֙ lò֣ʼ neʻĕdá̇֔r wĕ⁠lòֽʼ-ywòdé֥ʻa ʻawá֖̇l bòֽ̇şěţ׃"],[3,6,"הִכְרַ֣תִּי גוֹיִ֗ם נָשַׁ֨מּוּ֙ פִּנּוֹתָ֔⁠ם הֶחֱרַ֥בְתִּי חֽוּצוֹתָ֖⁠ם מִ⁠בְּלִ֣י עוֹבֵ֑ר נִצְדּ֧וּ עָרֵי⁠הֶ֛ם מִ⁠בְּלִי־אִ֖ישׁ מֵ⁠אֵ֥ין יוֹשֵֽׁב׃","hikĕra֣ţi̇y gwòyi֗m náşǎ֨ṁẇ֙ pi̇ṅwòţá֔⁠m heẖèra֥bĕţi̇y ẖֽẇẕwòţá֖⁠m mi⁠bĕ̇li֣y ʻwòbé֑r niẕĕḋ֧ẇ ʻáréy⁠he֛m mi⁠bĕ̇liy-ʼi֖yş̌ mé⁠ʼé֥yn ywòşéֽ̌b׃"],[3,7,"אָמַ֜רְתִּי אַךְ־תִּירְאִ֤י אוֹתִ⁠י֙ תִּקְחִ֣י מוּסָ֔ר וְ⁠לֹֽא־יִכָּרֵ֣ת מְעוֹנָ֔⁠הּ כֹּ֥ל אֲשֶׁר־פָּקַ֖דְתִּי עָלֶ֑י⁠הָ אָכֵן֙ הִשְׁכִּ֣ימוּ הִשְׁחִ֔יתוּ כֹּ֖ל עֲלִילוֹתָֽ⁠ם׃","ʼáma֜rĕţi̇y ʼakĕ-ţi̇yrĕʼi֤y ʼwòţi⁠y֙ ţi̇qĕẖi֣y mẇsá֔r wĕ⁠lòֽʼ-yiká̇ré֣ţ mĕʻwòná֔⁠ḣ kò֥̇l ʼàşěr-pá̇qa֖dĕţi̇y ʻále֑y⁠há ʼákén֙ hişĕ̌ki֣̇ymẇ hişĕ̌ẖi֔yţẇ kò֖̇l ʻàliylwòţáֽ⁠m׃"],[3,8,"לָ⁠כֵ֤ן חַכּוּ־לִ⁠י֙ נְאֻם־יְהוָ֔ה לְ⁠י֖וֹם קוּמִ֣⁠י לְ⁠עַ֑ד כִּ֣י מִשְׁפָּטִ⁠י֩ לֶ⁠אֱסֹ֨ף גּוֹיִ֜ם לְ⁠קָבְצִ֣⁠י מַמְלָכ֗וֹת לִ⁠שְׁפֹּ֨ךְ עֲלֵי⁠הֶ֤ם זַעְמִ⁠י֙ כֹּ֚ל חֲר֣וֹן אַפִּ֔⁠י כִּ֚י בְּ⁠אֵ֣שׁ קִנְאָתִ֔⁠י תֵּאָכֵ֖ל כָּל־הָ⁠אָֽרֶץ׃","lá⁠ké֤n ẖak̇ẇ-li⁠y֙ nĕʼum-yĕhwá֔h lĕ⁠y֖wòm qẇmi֣⁠y lĕ⁠ʻa֑d ki֣̇y mişĕ̌pá̇ti⁠y֩ le⁠ʼèsò֨p ġwòyi֜m lĕ⁠qábĕẕi֣⁠y mamĕlák֗wòţ li⁠şĕ̌pò̇֨kĕ ʻàléy⁠he֤m zaʻĕmi⁠y֙ kò֚̇l ẖàr֣wòn ʼapi̇֔⁠y ki֚̇y bĕ̇⁠ʼé֣ş̌ qinĕʼáţi֔⁠y ţé̇ʼáké֖l ká̇l-há⁠ʼáֽreẕ׃"],[3,9,"כִּֽי־אָ֛ז אֶהְפֹּ֥ךְ אֶל־עַמִּ֖ים שָׂפָ֣ה בְרוּרָ֑ה לִ⁠קְרֹ֤א כֻלָּ⁠ם֙ בְּ⁠שֵׁ֣ם יְהוָ֔ה לְ⁠עָבְד֖⁠וֹ שְׁכֶ֥ם אֶחָֽד׃","kiֽ̇y-ʼá֛z ʼehĕpò֥̇kĕ ʼel-ʻami֖̇ym şá̂pá֣h bĕrẇrá֑h li⁠qĕrò֤ʼ kulá̇⁠m֙ bĕ̇⁠şé֣̌m yĕhwá֔h lĕ⁠ʻábĕd֖⁠wò şĕ̌ke֥m ʼeẖáֽd׃"],[3,10,"מֵ⁠עֵ֖בֶר לְ⁠נַֽהֲרֵי־כ֑וּשׁ עֲתָרַ⁠י֙ בַּת־פוּצַ֔⁠י יוֹבִל֖וּ⁠ן מִנְחָתִֽ⁠י׃","mé⁠ʻé֖ber lĕ⁠naֽhàréy-k֑ẇş̌ ʻàţára⁠y֙ bȧţ-pẇẕa֔⁠y ywòbil֖ẇ⁠n minĕẖáţiֽ⁠y׃"],[3,11,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא לֹ֤א תֵב֨וֹשִׁי֙ מִ⁠כֹּ֣ל עֲלִילֹתַ֔יִ⁠ךְ אֲשֶׁ֥ר פָּשַׁ֖עַתְּ בִּ֑⁠י כִּי־אָ֣ז ׀ אָסִ֣יר מִ⁠קִּרְבֵּ֗⁠ךְ עַלִּיזֵי֙ גַּאֲוָתֵ֔⁠ךְ וְ⁠לֹֽא־תוֹסִ֧פִי לְ⁠גָבְהָ֛ה ע֖וֹד בְּ⁠הַ֥ר קָדְשִֽׁ⁠י׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ lò֤ʼ ţéb֨wòşǐy֙ mi⁠kò֣̇l ʻàliylòţa֔yi⁠kĕ ʼàşě֥r pá̇şǎ֖ʻaţĕ̇ bi֑̇⁠y ki̇y-ʼá֣z ׀ ʼási֣yr mi⁠qi̇rĕbé̇֗⁠kĕ ʻali̇yzéy֙ gȧʼàwáţé֔⁠kĕ wĕ⁠lòֽʼ-ţwòsi֧piy lĕ⁠gábĕhá֛h ʻ֖wòd bĕ̇⁠ha֥r qádĕşǐֽ⁠y׃"],[3,12,"וְ⁠הִשְׁאַרְתִּ֣י בְ⁠קִרְבֵּ֔⁠ךְ עַ֥ם עָנִ֖י וָ⁠דָ֑ל וְ⁠חָס֖וּ בְּ⁠שֵׁ֥ם יְהוָֽה׃","wĕ⁠hişĕ̌ʼarĕţi֣̇y bĕ⁠qirĕbé̇֔⁠kĕ ʻa֥m ʻáni֖y wá⁠dá֑l wĕ⁠ẖás֖ẇ bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[3,13,"שְׁאֵרִ֨ית יִשְׂרָאֵ֜ל לֹֽא־יַעֲשׂ֤וּ עַוְלָה֙ וְ⁠לֹא־יְדַבְּר֣וּ כָזָ֔ב וְ⁠לֹֽא־יִמָּצֵ֥א בְּ⁠פִי⁠הֶ֖ם לְשׁ֣וֹן תַּרְמִ֑ית כִּֽי־הֵ֛מָּה יִרְע֥וּ וְ⁠רָבְצ֖וּ וְ⁠אֵ֥ין מַחֲרִֽיד׃ס","şĕ̌ʼéri֨yţ yişĕ̂ráʼé֜l lòֽʼ-yaʻàş֤̂ẇ ʻawĕláh֙ wĕ⁠lòʼ-yĕdabĕ̇r֣ẇ kázá֔b wĕ⁠lòֽʼ-yimá̇ẕé֥ʼ bĕ̇⁠piy⁠he֖m lĕş֣̌wòn ţȧrĕmi֑yţ kiֽ̇y-hé֛má̇h yirĕʻ֥ẇ wĕ⁠rábĕẕ֖ẇ wĕ⁠ʼé֥yn maẖàriֽyd׃s"],[3,14,"רָנִּי֙ בַּת־צִיּ֔וֹן הָרִ֖יעוּ יִשְׂרָאֵ֑ל שִׂמְחִ֤י וְ⁠עָלְזִי֙ בְּ⁠כָל־לֵ֔ב בַּ֖ת יְרוּשָׁלִָֽם׃","ráni̇y֙ bȧţ-ẕiẏ֔wòn hári֖yʻẇ yişĕ̂ráʼé֑l şîmĕẖi֤y wĕ⁠ʻálĕziy֙ bĕ̇⁠kál-lé֔b bȧ֖ţ yĕrẇşá̌liáֽm׃"],[3,15,"הֵסִ֤יר יְהוָה֙ מִשְׁפָּטַ֔יִ⁠ךְ פִּנָּ֖ה אֹֽיְבֵ֑⁠ךְ מֶ֣לֶךְ יִשְׂרָאֵ֤ל ׀ יְהוָה֙ בְּ⁠קִרְבֵּ֔⁠ךְ לֹא־תִֽירְאִ֥י רָ֖ע עֽוֹד׃","hési֤yr yĕhwáh֙ mişĕ̌pá̇ta֔yi⁠kĕ pi̇ná֖̇h ʼòֽyĕbé֑⁠kĕ me֣lekĕ yişĕ̂ráʼé֤l ׀ yĕhwáh֙ bĕ̇⁠qirĕbé̇֔⁠kĕ lòʼ-ţiֽyrĕʼi֥y rá֖ʻ ʻֽwòd׃"],[3,16,"בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יֵאָמֵ֥ר לִירֽוּשָׁלִַ֖ם אַל־תִּירָ֑אִי צִיּ֖וֹן אַל־יִרְפּ֥וּ יָדָֽיִ⁠ךְ׃","bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yéʼámé֥r liyrֽẇşá̌lia֖m ʼal-ţi̇yrá֑ʼiy ẕiẏ֖wòn ʼal-yirĕṗ֥ẇ yádáֽyi⁠kĕ׃"],[3,17,"יְהוָ֧ה אֱלֹהַ֛יִ⁠ךְ בְּ⁠קִרְבֵּ֖⁠ך גִּבּ֣וֹר יוֹשִׁ֑יעַ יָשִׂ֨ישׂ עָלַ֜יִ⁠ךְ בְּ⁠שִׂמְחָ֗ה יַחֲרִישׁ֙ בְּ⁠אַ֣הֲבָת֔⁠וֹ יָגִ֥יל עָלַ֖יִ⁠ךְ בְּ⁠רִנָּֽה׃","yĕhwá֧h ʼèlòha֛yi⁠kĕ bĕ̇⁠qirĕbé֖̇⁠k gi̇ḃ֣wòr ywòşǐ֑yʻa yáşî֨yş̂ ʻála֜yi⁠kĕ bĕ̇⁠şîmĕẖá֗h yaẖàriyş̌֙ bĕ̇⁠ʼa֣hàbáţ֔⁠wò yági֥yl ʻála֖yi⁠kĕ bĕ̇⁠rináֽ̇h׃"],[3,18,"נוּגֵ֧י מִ⁠מּוֹעֵ֛ד אָסַ֖פְתִּי מִמֵּ֣⁠ךְ הָי֑וּ מַשְׂאֵ֥ת עָלֶ֖י⁠הָ חֶרְפָּֽה׃","nẇgé֧y mi⁠ṁwòʻé֛d ʼása֖pĕţi̇y mimé֣̇⁠kĕ háy֑ẇ maşĕ̂ʼé֥ţ ʻále֖y⁠há ẖerĕpáֽ̇h׃"],[3,19,"הִנְ⁠נִ֥י עֹשֶׂ֛ה אֶת־כָּל־מְעַנַּ֖יִ⁠ךְ בָּ⁠עֵ֣ת הַ⁠הִ֑יא וְ⁠הוֹשַׁעְתִּ֣י אֶת־הַ⁠צֹּלֵעָ֗ה וְ⁠הַ⁠נִּדָּחָה֙ אֲקַבֵּ֔ץ וְ⁠שַׂמְתִּי⁠ם֙ לִ⁠תְהִלָּ֣ה וּ⁠לְ⁠שֵׁ֔ם בְּ⁠כָל־הָ⁠אָ֖רֶץ בָּשְׁתָּֽ⁠ם׃","hinĕ⁠ni֥y ʻòşê֛h ʼeţ-ká̇l-mĕʻanȧ֖yi⁠kĕ bá̇⁠ʻé֣ţ ha⁠hi֑yʼ wĕ⁠hwòşǎʻĕţi֣̇y ʼeţ-ha⁠ẕò̇léʻá֗h wĕ⁠ha⁠ni̇dá̇ẖáh֙ ʼàqabé̇֔ẕ wĕ⁠şâmĕţi̇y⁠m֙ li⁠ţĕhilá֣̇h ẇ⁠lĕ⁠şé̌֔m bĕ̇⁠kál-há⁠ʼá֖reẕ bá̇şĕ̌ţáֽ̇⁠m׃"],[3,20,"בָּ⁠עֵ֤ת הַ⁠הִיא֙ אָבִ֣יא אֶתְ⁠כֶ֔ם וּ⁠בָ⁠עֵ֖ת קַבְּצִ֣⁠י אֶתְ⁠כֶ֑ם כִּֽי־אֶתֵּ֨ן אֶתְ⁠כֶ֜ם לְ⁠שֵׁ֣ם וְ⁠לִ⁠תְהִלָּ֗ה בְּ⁠כֹל֙ עַמֵּ֣י הָ⁠אָ֔רֶץ בְּ⁠שׁוּבִ֧⁠י אֶת־שְׁבוּתֵי⁠כֶ֛ם לְ⁠עֵינֵי⁠כֶ֖ם אָמַ֥ר יְהוָֽה׃","bá̇⁠ʻé֤ţ ha⁠hiyʼ֙ ʼábi֣yʼ ʼeţĕ⁠ke֔m ẇ⁠bá⁠ʻé֖ţ qabĕ̇ẕi֣⁠y ʼeţĕ⁠ke֑m kiֽ̇y-ʼeţé̇֨n ʼeţĕ⁠ke֜m lĕ⁠şé֣̌m wĕ⁠li⁠ţĕhilá̇֗h bĕ̇⁠kòl֙ ʻamé֣̇y há⁠ʼá֔reẕ bĕ̇⁠ş̌ẇbi֧⁠y ʼeţ-şĕ̌bẇţéy⁠ke֛m lĕ⁠ʻéynéy⁠ke֖m ʼáma֥r yĕhwáֽh׃"]],"fra-lsg1910":[[1,1,"La parole de l'Éternel qui fut adressée à Sophonie, fils de Cuschi, fils de Guedalia, fils d'Amaria, fils d'Ézéchias, au temps de Josias, fils d'Amon, roi de Juda.","La parole de l'Éternel qui fut adressée à Sophonie, fils de Cuschi, fils de Guedalia, fils d'Amaria, fils d'Ézéchias, au temps de Josias, fils d'Amon, roi de Juda."],[1,2,"Je détruirai tout sur la face de la terre, Dit l'Éternel.","Je détruirai tout sur la face de la terre, Dit l'Éternel."],[1,3,"Je détruirai les hommes et les bêtes, Les oiseaux du ciel et les poissons de la mer, Les objets de scandale, et les méchants avec eux; J'exterminerai les hommes de la face de la terre, Dit l'Éternel.","Je détruirai les hommes et les bêtes, Les oiseaux du ciel et les poissons de la mer, Les objets de scandale, et les méchants avec eux; J'exterminerai les hommes de la face de la terre, Dit l'Éternel."],[1,4,"J'étendrai ma main sur Juda, Et sur tous les habitants de Jérusalem; J'exterminerai de ce lieu les restes de Baal, Le nom de ses ministres et les prêtres avec eux,","J'étendrai ma main sur Juda, Et sur tous les habitants de Jérusalem; J'exterminerai de ce lieu les restes de Baal, Le nom de ses ministres et les prêtres avec eux,"],[1,5,"Ceux qui se prosternent sur les toits devant l'armée des cieux, Ceux qui se prosternent en jurant par l'Éternel Et en jurant par leur roi,","Ceux qui se prosternent sur les toits devant l'armée des cieux, Ceux qui se prosternent en jurant par l'Éternel Et en jurant par leur roi,"],[1,6,"Ceux qui se sont détournés de l'Éternel, Et ceux qui ne cherchent pas l'Éternel, Qui ne le consultent pas.","Ceux qui se sont détournés de l'Éternel, Et ceux qui ne cherchent pas l'Éternel, Qui ne le consultent pas."],[1,7,"Silence devant le Seigneur, l'Éternel! Car le jour de l'Éternel est proche, Car l'Éternel a préparé le sacrifice, Il a choisi ses conviés.","Silence devant le Seigneur, l'Éternel! Car le jour de l'Éternel est proche, Car l'Éternel a préparé le sacrifice, Il a choisi ses conviés."],[1,8,"Au jour du sacrifice de l'Éternel, Je châtierai les princes et les fils du roi, Et tous ceux qui portent des vêtements étrangers.","Au jour du sacrifice de l'Éternel, Je châtierai les princes et les fils du roi, Et tous ceux qui portent des vêtements étrangers."],[1,9,"En ce jour-là, je châtierai tous ceux qui sautent par-dessus le seuil, Ceux qui remplissent de violence et de fraude la maison de leur maître.","En ce jour-là, je châtierai tous ceux qui sautent par-dessus le seuil, Ceux qui remplissent de violence et de fraude la maison de leur maître."],[1,10,"En ce jour-là, dit l'Éternel, Il y aura des cris à la porte des poissons, Des lamentations dans l'autre quartier de la ville, Et un grand désastre sur les collines.","En ce jour-là, dit l'Éternel, Il y aura des cris à la porte des poissons, Des lamentations dans l'autre quartier de la ville, Et un grand désastre sur les collines."],[1,11,"Gémissez, habitants de Macthesch! Car tous ceux qui trafiquent sont détruits, Tous les hommes chargés d'argent sont exterminés.","Gémissez, habitants de Macthesch! Car tous ceux qui trafiquent sont détruits, Tous les hommes chargés d'argent sont exterminés."],[1,12,"En ce temps-là, je fouillerai Jérusalem avec des lampes, Et je châtierai les hommes qui reposent sur leurs lies, Et qui disent dans leur coeur: L'Éternel ne fait ni bien ni mal.","En ce temps-là, je fouillerai Jérusalem avec des lampes, Et je châtierai les hommes qui reposent sur leurs lies, Et qui disent dans leur coeur: L'Éternel ne fait ni bien ni mal."],[1,13,"Leurs biens seront au pillage, Et leurs maisons seront dévastées; Ils auront bâti des maisons, qu'ils n'habiteront plus, Ils auront planté des vignes, dont ils ne boiront plus le vin.","Leurs biens seront au pillage, Et leurs maisons seront dévastées; Ils auront bâti des maisons, qu'ils n'habiteront plus, Ils auront planté des vignes, dont ils ne boiront plus le vin."],[1,14,"Le grand jour de l'Éternel est proche, Il est proche, il arrive en toute hâte; Le jour de l'Éternel fait entendre sa voix, Et le héros pousse des cris amers.","Le grand jour de l'Éternel est proche, Il est proche, il arrive en toute hâte; Le jour de l'Éternel fait entendre sa voix, Et le héros pousse des cris amers."],[1,15,"Ce jour est un jour de fureur, Un jour de détresse et d'angoisse, Un jour de ravage et de destruction, Un jour de ténèbres et d'obscurité, Un jour de nuées et de brouillards,","Ce jour est un jour de fureur, Un jour de détresse et d'angoisse, Un jour de ravage et de destruction, Un jour de ténèbres et d'obscurité, Un jour de nuées et de brouillards,"],[1,16,"Un jour où retentiront la trompette et les cris de guerre Contre les villes fortes et les tours élevées.","Un jour où retentiront la trompette et les cris de guerre Contre les villes fortes et les tours élevées."],[1,17,"Je mettrai les hommes dans la détresse, Et ils marcheront comme des aveugles, Parce qu'ils ont péché contre l'Éternel; Je répandrai leur sang comme de la poussière, Et leur chair comme de l'ordure.","Je mettrai les hommes dans la détresse, Et ils marcheront comme des aveugles, Parce qu'ils ont péché contre l'Éternel; Je répandrai leur sang comme de la poussière, Et leur chair comme de l'ordure."],[1,18,"Ni leur argent ni leur or ne pourront les délivrer, Au jour de la fureur de l'Éternel; Par le feu de sa jalousie tout le pays sera consumé; Car il détruira soudain tous les habitants du pays.","Ni leur argent ni leur or ne pourront les délivrer, Au jour de la fureur de l'Éternel; Par le feu de sa jalousie tout le pays sera consumé; Car il détruira soudain tous les habitants du pays."],[2,1,"Rentrez en vous-mêmes, examinez-vous, Nation sans pudeur,","Rentrez en vous-mêmes, examinez-vous, Nation sans pudeur,"],[2,2,"Avant que le décret s'exécute Et que ce jour passe comme la balle, Avant que la colère ardente de l'Éternel fonde sur vous, Avant que le jour de la colère de l'Éternel fonde sur vous!","Avant que le décret s'exécute Et que ce jour passe comme la balle, Avant que la colère ardente de l'Éternel fonde sur vous, Avant que le jour de la colère de l'Éternel fonde sur vous!"],[2,3,"Cherchez l'Éternel, vous tous, humbles du pays, Qui pratiquez ses ordonnances! Recherchez la justice, recherchez l'humilité! Peut-être serez-vous épargnés au jour de la colère de l'Éternel.","Cherchez l'Éternel, vous tous, humbles du pays, Qui pratiquez ses ordonnances! Recherchez la justice, recherchez l'humilité! Peut-être serez-vous épargnés au jour de la colère de l'Éternel."],[2,4,"Car Gaza sera délaissée, Askalon sera réduite en désert, Asdod sera chassée en plein midi, Ékron sera déracinée.","Car Gaza sera délaissée, Askalon sera réduite en désert, Asdod sera chassée en plein midi, Ékron sera déracinée."],[2,5,"Malheur aux habitants des côtes de la mer, à la nation des Kéréthiens! L'Éternel a parlé contre toi, Canaan, pays des Philistins! Je te détruirai, tu n'auras plus d'habitants.","Malheur aux habitants des côtes de la mer, à la nation des Kéréthiens! L'Éternel a parlé contre toi, Canaan, pays des Philistins! Je te détruirai, tu n'auras plus d'habitants."],[2,6,"Les côtes de la mer seront des pâturages, des demeures pour les bergers, Et des parcs pour les troupeaux.","Les côtes de la mer seront des pâturages, des demeures pour les bergers, Et des parcs pour les troupeaux."],[2,7,"Ces côtes seront pour les restes de la maison de Juda; C'est là qu'ils paîtront; Ils reposeront le soir dans les maisons d'Askalon; Car l'Éternel, leur Dieu, ne les oubliera pas, Et il ramènera leurs captifs.","Ces côtes seront pour les restes de la maison de Juda; C'est là qu'ils paîtront; Ils reposeront le soir dans les maisons d'Askalon; Car l'Éternel, leur Dieu, ne les oubliera pas, Et il ramènera leurs captifs."],[2,8,"J'ai entendu les injures de Moab Et les outrages des enfants d'Ammon, Quand ils insultaient mon peuple Et s'élevaient avec arrogance contre ses frontières.","J'ai entendu les injures de Moab Et les outrages des enfants d'Ammon, Quand ils insultaient mon peuple Et s'élevaient avec arrogance contre ses frontières."],[2,9,"C'est pourquoi, je suis vivant! dit l'Éternel des armées, le Dieu d'Israël, Moab sera comme Sodome, et les enfants d'Ammon comme Gomorrhe, Un lieu couvert de ronces, une mine de sel, un désert pour toujours; Le reste de mon peuple les pillera, Le reste de ma nation les possédera.","C'est pourquoi, je suis vivant! dit l'Éternel des armées, le Dieu d'Israël, Moab sera comme Sodome, et les enfants d'Ammon comme Gomorrhe, Un lieu couvert de ronces, une mine de sel, un désert pour toujours; Le reste de mon peuple les pillera, Le reste de ma nation les possédera."],[2,10,"Cela leur arrivera pour leur orgueil, Parce qu'ils ont insulté et traité avec arrogance Le peuple de l'Éternel des armées.","Cela leur arrivera pour leur orgueil, Parce qu'ils ont insulté et traité avec arrogance Le peuple de l'Éternel des armées."],[2,11,"L'Éternel sera terrible contre eux, Car il anéantira tous les dieux de la terre; Et chacun se prosternera devant lui dans son pays, Dans toutes les îles des nations.","L'Éternel sera terrible contre eux, Car il anéantira tous les dieux de la terre; Et chacun se prosternera devant lui dans son pays, Dans toutes les îles des nations."],[2,12,"Vous aussi, Éthiopiens, Vous serez frappés par mon épée.","Vous aussi, Éthiopiens, Vous serez frappés par mon épée."],[2,13,"Il étendra sa main sur le septentrion, Il détruira l'Assyrie, Et il fera de Ninive une solitude, Une terre aride comme le désert.","Il étendra sa main sur le septentrion, Il détruira l'Assyrie, Et il fera de Ninive une solitude, Une terre aride comme le désert."],[2,14,"Des troupeaux se coucheront au milieu d'elle, Des animaux de toute espèce; Le pélican et le hérisson Habiteront parmi les chapiteaux de ses colonnes; Des cris retentiront aux fenêtres; La dévastation sera sur le seuil, Car les lambris de cèdre seront arrachés.","Des troupeaux se coucheront au milieu d'elle, Des animaux de toute espèce; Le pélican et le hérisson Habiteront parmi les chapiteaux de ses colonnes; Des cris retentiront aux fenêtres; La dévastation sera sur le seuil, Car les lambris de cèdre seront arrachés."],[2,15,"Voilà donc cette ville joyeuse, Qui s'assied avec assurance, Et qui dit en son coeur: Moi, et rien que moi! Eh quoi! elle est en ruines, C'est un repaire pour les bêtes! Tous ceux qui passeront près d'elle Siffleront et agiteront la main.","Voilà donc cette ville joyeuse, Qui s'assied avec assurance, Et qui dit en son coeur: Moi, et rien que moi! Eh quoi! elle est en ruines, C'est un repaire pour les bêtes! Tous ceux qui passeront près d'elle Siffleront et agiteront la main."],[3,1,"Malheur à la ville rebelle et souillée, À la ville pleine d'oppresseurs!","Malheur à la ville rebelle et souillée, À la ville pleine d'oppresseurs!"],[3,2,"Elle n'écoute aucune voix, Elle n'a point égard à la correction, Elle ne se confie pas en l'Éternel, Elle ne s'approche pas de son Dieu.","Elle n'écoute aucune voix, Elle n'a point égard à la correction, Elle ne se confie pas en l'Éternel, Elle ne s'approche pas de son Dieu."],[3,3,"Ses chefs au milieu d'elle sont des lions rugissants; Ses juges sont des loups du soir qui ne gardent rien pour le matin.","Ses chefs au milieu d'elle sont des lions rugissants; Ses juges sont des loups du soir qui ne gardent rien pour le matin."],[3,4,"Ses prophètes sont téméraires, infidèles; Ses sacrificateurs profanent les choses saintes, violent la loi.","Ses prophètes sont téméraires, infidèles; Ses sacrificateurs profanent les choses saintes, violent la loi."],[3,5,"L'Éternel est juste au milieu d'elle, Il ne commet point d'iniquité; Chaque matin il produit à la lumière ses jugements, Sans jamais y manquer; Mais celui qui est inique ne connaît pas la honte.","L'Éternel est juste au milieu d'elle, Il ne commet point d'iniquité; Chaque matin il produit à la lumière ses jugements, Sans jamais y manquer; Mais celui qui est inique ne connaît pas la honte."],[3,6,"J'ai exterminé des nations; leurs tours sont détruites; J'ai dévasté leurs rues, plus de passants! Leurs villes sont ravagées, plus d'hommes, plus d'habitants!","J'ai exterminé des nations; leurs tours sont détruites; J'ai dévasté leurs rues, plus de passants! Leurs villes sont ravagées, plus d'hommes, plus d'habitants!"],[3,7,"Je disais: Si du moins tu voulais me craindre, Avoir égard à la correction, Ta demeure ne serait pas détruite, Tous les châtiments dont je t'ai menacée n'arriveraient pas; Mais ils se sont hâtés de pervertir toutes leurs actions.","Je disais: Si du moins tu voulais me craindre, Avoir égard à la correction, Ta demeure ne serait pas détruite, Tous les châtiments dont je t'ai menacée n'arriveraient pas; Mais ils se sont hâtés de pervertir toutes leurs actions."],[3,8,"Attendez-moi donc, dit l'Éternel, Au jour où je me lèverai pour le butin, Car j'ai résolu de rassembler les nations, De rassembler les royaumes, Pour répandre sur eux ma fureur, Toute l'ardeur de ma colère; Car par le feu de ma jalousie tout le pays sera consumé.","Attendez-moi donc, dit l'Éternel, Au jour où je me lèverai pour le butin, Car j'ai résolu de rassembler les nations, De rassembler les royaumes, Pour répandre sur eux ma fureur, Toute l'ardeur de ma colère; Car par le feu de ma jalousie tout le pays sera consumé."],[3,9,"Alors je donnerai aux peuples des lèvres pures, Afin qu'ils invoquent tous le nom de l'Éternel, Pour le servir d'un commun accord.","Alors je donnerai aux peuples des lèvres pures, Afin qu'ils invoquent tous le nom de l'Éternel, Pour le servir d'un commun accord."],[3,10,"D'au delà des fleuves de l'Éthiopie Mes adorateurs, mes dispersés, m'apporteront des offrandes.","D'au delà des fleuves de l'Éthiopie Mes adorateurs, mes dispersés, m'apporteront des offrandes."],[3,11,"En ce jour-là, tu n'auras plus à rougir de toutes tes actions Par lesquelles tu as péché contre moi; Car alors j'ôterai du milieu de toi ceux qui triomphaient avec arrogance, Et tu ne t'enorgueilliras plus sur ma montagne sainte.","En ce jour-là, tu n'auras plus à rougir de toutes tes actions Par lesquelles tu as péché contre moi; Car alors j'ôterai du milieu de toi ceux qui triomphaient avec arrogance, Et tu ne t'enorgueilliras plus sur ma montagne sainte."],[3,12,"Je laisserai au milieu de toi un peuple humble et petit, Qui trouvera son refuge dans le nom de l'Éternel.","Je laisserai au milieu de toi un peuple humble et petit, Qui trouvera son refuge dans le nom de l'Éternel."],[3,13,"Les restes d'Israël ne commettront point d'iniquité, Ils ne diront point de mensonges, Et il ne se trouvera pas dans leur bouche une langue trompeuse; Mais ils paîtront, ils se reposeront, et personne ne les troublera.","Les restes d'Israël ne commettront point d'iniquité, Ils ne diront point de mensonges, Et il ne se trouvera pas dans leur bouche une langue trompeuse; Mais ils paîtront, ils se reposeront, et personne ne les troublera."],[3,14,"Pousse des cris de joie, fille de Sion! Pousse des cris d'allégresse, Israël! Réjouis-toi et triomphe de tout ton coeur, fille de Jérusalem!","Pousse des cris de joie, fille de Sion! Pousse des cris d'allégresse, Israël! Réjouis-toi et triomphe de tout ton coeur, fille de Jérusalem!"],[3,15,"L'Éternel a détourné tes châtiments, Il a éloigné ton ennemi; Le roi d'Israël, l'Éternel, est au milieu de toi; Tu n'as plus de malheur à éprouver.","L'Éternel a détourné tes châtiments, Il a éloigné ton ennemi; Le roi d'Israël, l'Éternel, est au milieu de toi; Tu n'as plus de malheur à éprouver."],[3,16,"En ce jour-là, on dira à Jérusalem: Ne crains rien! Sion, que tes mains ne s'affaiblissent pas!","En ce jour-là, on dira à Jérusalem: Ne crains rien! Sion, que tes mains ne s'affaiblissent pas!"],[3,17,"L'Éternel, ton Dieu, est au milieu de toi, comme un héros qui sauve; Il fera de toi sa plus grande joie; Il gardera le silence dans son amour; Il aura pour toi des transports d'allégresse.","L'Éternel, ton Dieu, est au milieu de toi, comme un héros qui sauve; Il fera de toi sa plus grande joie; Il gardera le silence dans son amour; Il aura pour toi des transports d'allégresse."],[3,18,"Je rassemblerai ceux qui sont dans la tristesse, loin des fêtes solennelles, Ceux qui sont sortis de ton sein; L'opprobre pèse sur eux.","Je rassemblerai ceux qui sont dans la tristesse, loin des fêtes solennelles, Ceux qui sont sortis de ton sein; L'opprobre pèse sur eux."],[3,19,"Voici, en ce temps-là, j'agirai contre tous tes oppresseurs; Je délivrerai les boiteux et je recueillerai ceux qui ont été chassés, Je ferai d'eux un sujet de louange et de gloire Dans tous les pays où ils sont en opprobre.","Voici, en ce temps-là, j'agirai contre tous tes oppresseurs; Je délivrerai les boiteux et je recueillerai ceux qui ont été chassés, Je ferai d'eux un sujet de louange et de gloire Dans tous les pays où ils sont en opprobre."],[3,20,"En ce temps-là, je vous ramènerai; En ce temps-là, je vous rassemblerai; Car je ferai de vous un sujet de gloire et de louange Parmi tous les peuples de la terre, Quand je ramènerai vos captifs sous vos yeux, Dit l'Éternel.","En ce temps-là, je vous ramènerai; En ce temps-là, je vous rassemblerai; Car je ferai de vous un sujet de gloire et de louange Parmi tous les peuples de la terre, Quand je ramènerai vos captifs sous vos yeux, Dit l'Éternel."]],"spa-rv1909":[[1,1,"PALABRAde JehováquefuéáSofoníashijode Cushi, hijode Gedalías, hijode Amarías, hijode Ezechîas, en díasde Josíashijode Amón, reyde Judá.","PALABRAde JehováquefuéáSofoníashijode Cushi, hijode Gedalías, hijode Amarías, hijode Ezechîas, en díasde Josíashijode Amón, reyde Judá."],[1,2,"Destruirédel todo todaslas cosas de sobrela hazde la tierra, diceJehová.","Destruirédel todo todaslas cosas de sobrela hazde la tierra, diceJehová."],[1,3,"Destruirélos hombresy las bestias; destruirélas avesdel cielo, y los pecesde la mar, y las piedras de tropiezo con los impíos; y talarélos hombresde sobrela hazde la tierra, diceJehová.","Destruirélos hombresy las bestias; destruirélas avesdel cielo, y los pecesde la mar, y las piedras de tropiezo con los impíos; y talarélos hombresde sobrela hazde la tierra, diceJehová."],[1,4,"Y extenderémi manosobreJudá, y sobretodoslos moradoresde Jerusalem, y exterminarédeeste lugar el remanente deBaal, y el nombredelos Chemarimconlos sacerdotes;","Y extenderémi manosobreJudá, y sobretodoslos moradoresde Jerusalem, y exterminarédeeste lugar el remanente deBaal, y el nombredelos Chemarimconlos sacerdotes;"],[1,5,"Y á los que se inclinan sobrelos terradosal ejércitodel cielo; y á los que se inclinan jurandopor Jehováy jurandopor su rey;","Y á los que se inclinan sobrelos terradosal ejércitodel cielo; y á los que se inclinan jurandopor Jehováy jurandopor su rey;"],[1,6,"Y á los que tornan atrás de en posde Jehová; y á los quenobuscaroná Jehová, nipreguntaron por él.","Y á los que tornan atrás de en posde Jehová; y á los quenobuscaroná Jehová, nipreguntaron por él."],[1,7,"Callaen la presenciadel SeñorJehová, porqueel díade Jehováestá cercano; porqueJehováha aparejadosacrificio, prevenidoha sus convidados.","Callaen la presenciadel SeñorJehová, porqueel díade Jehováestá cercano; porqueJehováha aparejadosacrificio, prevenidoha sus convidados."],[1,8,"Y será que en el díadel sacrificiode Jehová, haré visitaciónsobre los príncipes, y sobre los hijosdel rey, y sobre todoslos que vistenvestidoextranjero.","Y será que en el díadel sacrificiode Jehová, haré visitaciónsobre los príncipes, y sobre los hijosdel rey, y sobre todoslos que vistenvestidoextranjero."],[1,9,"Asimismo haré visitaciónen aquel díasobre todoslos que saltanla puerta, los que hinchen de roboy de engañolas casasde sus señores.","Asimismo haré visitaciónen aquel díasobre todoslos que saltanla puerta, los que hinchen de roboy de engañolas casasde sus señores."],[1,10,"Y habráen aquel día, diceJehová, vozde clamordesdela puertadel pescado, y aullido desdela segunda, y grandequebrantamientodesdelos collados.","Y habráen aquel día, diceJehová, vozde clamordesdela puertadel pescado, y aullido desdela segunda, y grandequebrantamientodesdelos collados."],[1,11,"Aullad, moradoresde Mactes, porquetodoel pueblomercaderes destruído; taladosson todoslos que traíandinero.","Aullad, moradoresde Mactes, porquetodoel pueblomercaderes destruído; taladosson todoslos que traíandinero."],[1,12,"Y seráen aquel tiempo, que yo escudriñaréá Jerusalemcon candiles, y haré visitaciónsobrelos hombresque están sentados sobre sus heces, los cuales dicenen su corazón: Jehovániharábien nimal.","Y seráen aquel tiempo, que yo escudriñaréá Jerusalemcon candiles, y haré visitaciónsobrelos hombresque están sentados sobre sus heces, los cuales dicenen su corazón: Jehovániharábien nimal."],[1,13,"Serápor tanto saqueadasu hacienda, y sus casasasoladas: y edificaráncasas, mas nolas habitarán; y plantaránviñas, mas nobeberánel vinode ellas.","Serápor tanto saqueadasu hacienda, y sus casasasoladas: y edificaráncasas, mas nolas habitarán; y plantaránviñas, mas nobeberánel vinode ellas."],[1,14,"Cercanoestá el díagrandede Jehová, cercanoy muypresuroso; vozamargadel díade Jehová; gritaráallíel valiente.","Cercanoestá el díagrandede Jehová, cercanoy muypresuroso; vozamargadel díade Jehová; gritaráallíel valiente."],[1,15,"Díade iraaquel día, díade angustiay de aprieto, díade alborotoy de asolamiento, díade tinieblay de oscuridad, díade nubladoy de entenebrecimiento,","Díade iraaquel día, díade angustiay de aprieto, díade alborotoy de asolamiento, díade tinieblay de oscuridad, díade nubladoy de entenebrecimiento,"],[1,16,"Díade trompetay de algazara, sobrelas ciudadesfuertes, y sobrelas altastorres.","Díade trompetay de algazara, sobrelas ciudadesfuertes, y sobrelas altastorres."],[1,17,"Y atribularélos hombres, y andaráncomo ciegos, porquepecaroncontra Jehová: y la sangrede ellos será derramadacomo polvo, y su carnecomo estiércol.","Y atribularélos hombres, y andaráncomo ciegos, porquepecaroncontra Jehová: y la sangrede ellos será derramadacomo polvo, y su carnecomo estiércol."],[1,18,"Nisu platanisu oropodrálibrarlos en el díade la irade Jehová; pues todala tierraserá consumidacon el fuegode su celo: porqueciertamenteconsumaciónapresuradaharácon todoslos moradoresde la tierra.","Nisu platanisu oropodrálibrarlos en el díade la irade Jehová; pues todala tierraserá consumidacon el fuegode su celo: porqueciertamenteconsumaciónapresuradaharácon todoslos moradoresde la tierra."],[2,1,"CONGREGAOSy meditad, gentenoamable,","CONGREGAOSy meditad, gentenoamable,"],[2,2,"Antesque pára el decreto, y el díase pasecomo el tamo; antesque vengasobrevosotros el furorde la irade Jehová, antesque el díade la irade Jehovávengasobrevosotros.","Antesque pára el decreto, y el díase pasecomo el tamo; antesque vengasobrevosotros el furorde la irade Jehová, antesque el díade la irade Jehovávengasobrevosotros."],[2,3,"Buscadá Jehovátodoslos humildesde la tierra, quepusisteis en obrasu juicio; buscadjusticia, buscadmansedumbre: quizásseréis guardadosen el díadel enojode Jehová.","Buscadá Jehovátodoslos humildesde la tierra, quepusisteis en obrasu juicio; buscadjusticia, buscadmansedumbre: quizásseréis guardadosen el díadel enojode Jehová."],[2,4,"PorqueGazaserádesamparada, y Ascalónasolada: saquearáná Asdoden el medio día, y Ecrónserádesarraigada.","PorqueGazaserádesamparada, y Ascalónasolada: saquearáná Asdoden el medio día, y Ecrónserádesarraigada."],[2,5,"¡Ayde los que moraná la partede la mar, de la gentede Cheretim! La palabrade Jehováes contravosotros, oh Canaán, tierrade Palestinos, que te haré destruirhasta no quedarmorador.","¡Ayde los que moraná la partede la mar, de la gentede Cheretim! La palabrade Jehováes contravosotros, oh Canaán, tierrade Palestinos, que te haré destruirhasta no quedarmorador."],[2,6,"Y serála partede la marpor moradas de cabañasde pastores, y corralesde ovejas.","Y serála partede la marpor moradas de cabañasde pastores, y corralesde ovejas."],[2,7,"Y seráaquella parte para el resto de la casade Judá; allí apacentarán: en las casasde Ascalóndormiráná la noche; porqueJehovásu Dioslos visitará, y tornarásus cautivos.","Y seráaquella parte para el resto de la casade Judá; allí apacentarán: en las casasde Ascalóndormiráná la noche; porqueJehovásu Dioslos visitará, y tornarásus cautivos."],[2,8,"Yo he oídolas afrentasde Moab, y los denuestosde los hijosde Ammóncon quedeshonraroná mi pueblo, y se engrandecieronsobresu término.","Yo he oídolas afrentasde Moab, y los denuestosde los hijosde Ammóncon quedeshonraroná mi pueblo, y se engrandecieronsobresu término."],[2,9,"Por tanto, vivoyo, diceJehováde los ejércitos, Diosde Israel, queMoabserácomo Sodoma, y los hijosde Ammóncomo Gomorra; campode ortigas, y minade sal, y asolamientoperpetuo: el resto de mipueblolos saqueará, y el resto de migentelos heredará.","Por tanto, vivoyo, diceJehováde los ejércitos, Diosde Israel, queMoabserácomo Sodoma, y los hijosde Ammóncomo Gomorra; campode ortigas, y minade sal, y asolamientoperpetuo: el resto de mipueblolos saqueará, y el resto de migentelos heredará."],[2,10,"Estoles vendrá porsusoberbia, porqueafrentaron, y se engrandecieroncontrael pueblode Jehováde los ejércitos.","Estoles vendrá porsusoberbia, porqueafrentaron, y se engrandecieroncontrael pueblode Jehováde los ejércitos."],[2,11,"Terribleserá Jehovácontraellos, porqueenervará á todoslos diosesde la tierra; y cada uno desde su lugar seinclinaráá él, todaslas islas de las gentes.","Terribleserá Jehovácontraellos, porqueenervará á todoslos diosesde la tierra; y cada uno desde su lugar seinclinaráá él, todaslas islas de las gentes."],[2,12,"Vosotrostambiénlos de Etiopíaseréis muertoscon mi espada.","Vosotrostambiénlos de Etiopíaseréis muertoscon mi espada."],[2,13,"Y extenderásu manosobreel aquilón, y destruiráal Assur, y pondráá Níniveen asolamiento, y en secadalcomo un desierto.","Y extenderásu manosobreel aquilón, y destruiráal Assur, y pondráá Níniveen asolamiento, y en secadalcomo un desierto."],[2,14,"Y rebañosde ganado harán enella majada, todaslas bestiasde las gentes; el onocrótalotambiény el erizodormiránensus umbrales: suvozcantaráenlas ventanas; asolaciónserá enlas puertas, porquesu enmaderamiento decedroserá descubierto.","Y rebañosde ganado harán enella majada, todaslas bestiasde las gentes; el onocrótalotambiény el erizodormiránensus umbrales: suvozcantaráenlas ventanas; asolaciónserá enlas puertas, porquesu enmaderamiento decedroserá descubierto."],[2,15,"Estaes la ciudadalegreque estabaconfiada, la que decíaen su corazón: Yo, y nomás. ¡Cómofuéen asolamiento, en camade bestias! Cualquieraque pasarejuntoá ella silbará, menearásu mano.","Estaes la ciudadalegreque estabaconfiada, la que decíaen su corazón: Yo, y nomás. ¡Cómofuéen asolamiento, en camade bestias! Cualquieraque pasarejuntoá ella silbará, menearásu mano."],[3,1,"¡AYde la ciudadensuciada y contaminadayopresora!","¡AYde la ciudadensuciada y contaminadayopresora!"],[3,2,"Noescuchóla voz, nirecibióla disciplina: nose confióen Jehová, nose acercóásu Dios.","Noescuchóla voz, nirecibióla disciplina: nose confióen Jehová, nose acercóásu Dios."],[3,3,"Sus príncipesen mediode ella son leonesbramadores: sus jueces, lobosde tarde que nodejanhueso para la mañana:","Sus príncipesen mediode ella son leonesbramadores: sus jueces, lobosde tarde que nodejanhueso para la mañana:"],[3,4,"Sus profetas, livianos, hombresprevaricadores: sus sacerdotescontaminaronel santuario, falsearonla ley.","Sus profetas, livianos, hombresprevaricadores: sus sacerdotescontaminaronel santuario, falsearonla ley."],[3,5,"Jehovájustoen mediode ella, noharáiniquidad: de mañanasacaráá luzsu juicio, nuncafalta: mas el perversonotiene vergüenza.","Jehovájustoen mediode ella, noharáiniquidad: de mañanasacaráá luzsu juicio, nuncafalta: mas el perversonotiene vergüenza."],[3,6,"Hice talargentes; sus castillosestán asolados; hice desiertassus calles, hasta noquedar quien pase: sus ciudadesestán asoladashasta noquedar hombre, hasta noquedar morador.","Hice talargentes; sus castillosestán asolados; hice desiertassus calles, hasta noquedar quien pase: sus ciudadesestán asoladashasta noquedar hombre, hasta noquedar morador."],[3,7,"Dije: Ciertamenteme temerás, recibiráscorrección; y noserá su habitaciónderruídapor todoaquello sobre quelos visité. Masellos se levantaron de mañana, y corrompierontodassus obras.","Dije: Ciertamenteme temerás, recibiráscorrección; y noserá su habitaciónderruídapor todoaquello sobre quelos visité. Masellos se levantaron de mañana, y corrompierontodassus obras."],[3,8,"Por tanto, esperadme, diceJehová, al díaque me levantaréal despojo: porquemi determinaciónes reunir las gentes, juntarlos reinos, para derramarsobreellos mi enojo, todoel furorde mi ira; porquedel fuegode mi celoserá consumidatodala tierra.","Por tanto, esperadme, diceJehová, al díaque me levantaréal despojo: porquemi determinaciónes reunir las gentes, juntarlos reinos, para derramarsobreellos mi enojo, todoel furorde mi ira; porquedel fuegode mi celoserá consumidatodala tierra."],[3,9,"Porentoncesvolveréyo álos pueblosel labiolimpio, para que todosinvoquenel nombrede Jehová, para que de un consentimientole sirvan.","Porentoncesvolveréyo álos pueblosel labiolimpio, para que todosinvoquenel nombrede Jehová, para que de un consentimientole sirvan."],[3,10,"De esa parte de los ríosde Etiopía, mis suplicantes, la hijade mis esparcidos, me traeránofrenda.","De esa parte de los ríosde Etiopía, mis suplicantes, la hijade mis esparcidos, me traeránofrenda."],[3,11,"En aquel díanoserás avergonzadapor ningunade tus obrascon quete rebelastecontra mí; porqueentoncesquitaréde en mediode ti los quese alegranen tu soberbia, y nunca máste ensoberbecerásdel montede mi santidad.","En aquel díanoserás avergonzadapor ningunade tus obrascon quete rebelastecontra mí; porqueentoncesquitaréde en mediode ti los quese alegranen tu soberbia, y nunca máste ensoberbecerásdel montede mi santidad."],[3,12,"Y dejaréen mediode ti un pueblohumildey pobre, los cuales esperarán en el nombrede Jehová.","Y dejaréen mediode ti un pueblohumildey pobre, los cuales esperarán en el nombrede Jehová."],[3,13,"El resto de Israelnoharáiniquidad, nidirá mentira, nien bocade ellosse hallarálenguaengañosa: porqueellosseránapacentadosy dormirán, y nohabrá quien los espante.","El resto de Israelnoharáiniquidad, nidirá mentira, nien bocade ellosse hallarálenguaengañosa: porqueellosseránapacentadosy dormirán, y nohabrá quien los espante."],[3,14,"Canta, oh hijade Sión: da voces de júbilo, oh Israel; gózatey regocíjatede todocorazón, hijade Jerusalem.","Canta, oh hijade Sión: da voces de júbilo, oh Israel; gózatey regocíjatede todocorazón, hijade Jerusalem."],[3,15,"Jehováha apartadotus juicios, ha echadofuera tus enemigos: Jehováes Reyde Israelen mediode ti; nuncamásverásmal.","Jehováha apartadotus juicios, ha echadofuera tus enemigos: Jehováes Reyde Israelen mediode ti; nuncamásverásmal."],[3,16,"En aquel tiempose diráá Jerusalem: Notemas: Sión, nose debilitentus manos.","En aquel tiempose diráá Jerusalem: Notemas: Sión, nose debilitentus manos."],[3,17,"Jehováen mediode ti, poderoso, él salvará; gozarásesobreti con alegría, callaráde amor, se regocijarásobreti con cantar.","Jehováen mediode ti, poderoso, él salvará; gozarásesobreti con alegría, callaráde amor, se regocijarásobreti con cantar."],[3,18,"Reuniréá los fastidiadospor causa dellargotiempo; tuyosfueron; para quienesel oprobiode ellaera una carga.","Reuniréá los fastidiadospor causa dellargotiempo; tuyosfueron; para quienesel oprobiode ellaera una carga."],[3,19,"He aquí, en aquel tiempoyo apremiaréá todostusopresores; y salvaréla coja, y recogeréla descarriada; y pondrélospor alabanzay por renombreen todopaísde confusión.","He aquí, en aquel tiempoyo apremiaréá todostusopresores; y salvaréla coja, y recogeréla descarriada; y pondrélospor alabanzay por renombreen todopaísde confusión."],[3,20,"En aquel tiempoyo os traeré, en aquel tiempoos reuniréyo; puesos darépor renombrey por alabanzaentre todoslos pueblosde la tierra, cuando tornarévuestros cautivosdelante de vuestros ojos, diceJehová.","En aquel tiempoyo os traeré, en aquel tiempoos reuniréyo; puesos darépor renombrey por alabanzaentre todoslos pueblosde la tierra, cuando tornarévuestros cautivosdelante de vuestros ojos, diceJehová."]],"rus-synodal":[[1,1,"Слово Господне, которое было к Софонии, сыну Хусия, сыну Годолии, сыну Амории, сыну Езекии, во дни Иосии, сына Амонова, царя Иудейского.","Slovo Gospodne, kotoroe bylo k Sofonii, synu Husiâ, synu Godolii, synu Amorii, synu Ezekii, vo dni Iosii, syna Amonova, carâ Iudejskogo."],[1,2,"Все истреблю с лица земли, говорит Господь:","Vse istreblû s lica zemli, govorit Gospodʹ:"],[1,3,"истреблю людей и скот, истреблю птиц небесных и рыб морских, и соблазны вместе с нечестивыми; истреблю людей с лица земли, говорит Господь.","istreblû lûdej i skot, istreblû ptic nebesnyh i ryb morskih, i soblazny vmeste s nečestivymi; istreblû lûdej s lica zemli, govorit Gospodʹ."],[1,4,"И простру руку Мою на Иудею и на всех жителей Иерусалима: истреблю с места сего остатки Ваала, имя жрецов со священниками,","I prostru ruku Moû na Iudeû i na vseh žitelej Ierusalima: istreblû s mesta sego ostatki Vaala, imâ žrecov so svâŝennikami,"],[1,5,"и тех, которые на кровлях поклоняются воинству небесному, и тех поклоняющихся, которые клянутся Господом и клянутся царем своим,","i teh, kotorye na krovlâh poklonâûtsâ voinstvu nebesnomu, i teh poklonâûŝihsâ, kotorye klânutsâ Gospodom i klânutsâ carem svoim,"],[1,6,"и тех, которые отступили от Господа, не искали Господа и не вопрошали о Нем.","i teh, kotorye otstupili ot Gospoda, ne iskali Gospoda i ne voprošali o Nem."],[1,7,"Умолкни пред лицом Господа Бога! ибо близок день Господень: уже приготовил Господь жертвенное заклание, назначил, кого позвать.","Umolkni pred licom Gospoda Boga! ibo blizok denʹ Gospodenʹ: uže prigotovil Gospodʹ žertvennoe zaklanie, naznačil, kogo pozvatʹ."],[1,8,"И будет в день жертвы Господней: Я посещу князей и сыновей царя и всех, одевающихся в одежду иноплеменников;","I budet v denʹ žertvy Gospodnej: Â poseŝu knâzej i synovej carâ i vseh, odevaûŝihsâ v odeždu inoplemennikov;"],[1,9,"посещу в тот день всех, которые перепрыгивают через порог, которые дом Господа своего наполняют насилием и обманом.","poseŝu v tot denʹ vseh, kotorye pereprygivaût čerez porog, kotorye dom Gospoda svoego napolnâût nasiliem i obmanom."],[1,10,"И будет в тот день, говорит Господь, вопль у ворот рыбных и рыдание у других ворот и великое разрушение на холмах.","I budet v tot denʹ, govorit Gospodʹ, voplʹ u vorot rybnyh i rydanie u drugih vorot i velikoe razrušenie na holmah."],[1,11,"Рыдайте, жители нижней части города, ибо исчезнет весь торговый народ и истреблены будут обремененные серебром.","Rydajte, žiteli nižnej časti goroda, ibo isčeznet vesʹ torgovyj narod i istrebleny budut obremenennye serebrom."],[1,12,"И будет в то время: Я со светильником осмотрю Иерусалим и накажу тех, которые сидят на дрожжах своих и говорят в сердце своем: «не делает Господь ни добра, ни зла».","I budet v to vremâ: Â so svetilʹnikom osmotrû Ierusalim i nakažu teh, kotorye sidât na drožžah svoih i govorât v serdce svoem: «ne delaet Gospodʹ ni dobra, ni zla»."],[1,13,"И обратятся богатства их в добычу и дома их – в запустение; они построят дома, а жить в них не будут, насадят виноградники, а вина из них не будут пить.","I obratâtsâ bogatstva ih v dobyču i doma ih – v zapustenie; oni postroât doma, a žitʹ v nih ne budut, nasadât vinogradniki, a vina iz nih ne budut pitʹ."],[1,14,"Близок великий день Господа, близок, и очень поспешает: уже слышен голос дня Господня; горько возопиет тогда и самый храбрый!","Blizok velikij denʹ Gospoda, blizok, i očenʹ pospešaet: uže slyšen golos dnâ Gospodnâ; gorʹko vozopiet togda i samyj hrabryj!"],[1,15,"День гнева – день сей, день скорби и тесноты, день опустошения и разорения, день тьмы и мрака, день облака и мглы,","Denʹ gneva – denʹ sej, denʹ skorbi i tesnoty, denʹ opustošeniâ i razoreniâ, denʹ tʹmy i mraka, denʹ oblaka i mgly,"],[1,16,"день трубы и бранного крика против укрепленных городов и высоких башен.","denʹ truby i brannogo krika protiv ukreplennyh gorodov i vysokih bašen."],[1,17,"И Я стесню людей, и они будут ходить как слепые, потому что они согрешили против Господа, и разметана будет кровь их, как прах, и плоть их – как помет.","I Â stesnû lûdej, i oni budut hoditʹ kak slepye, potomu čto oni sogrešili protiv Gospoda, i razmetana budet krovʹ ih, kak prah, i plotʹ ih – kak pomet."],[1,18,"Ни серебро их, ни золото их не может спасти их в день гнева Господа, и огнем ревности Его пожрана будет вся эта земля, ибо истребление, и притом внезапное, совершит Он над всеми жителями земли.","Ni serebro ih, ni zoloto ih ne možet spasti ih v denʹ gneva Gospoda, i ognem revnosti Ego požrana budet vsâ éta zemlâ, ibo istreblenie, i pritom vnezapnoe, soveršit On nad vsemi žitelâmi zemli."],[2,1,"Исследуйте себя внимательно, исследуйте, народ необузданный,","Issledujte sebâ vnimatelʹno, issledujte, narod neobuzdannyj,"],[2,2,"доколе не пришло определение – день пролетит как мякина – доколе не пришел на вас пламенный гнев Господень, доколе не наступил для вас день ярости Господней.","dokole ne prišlo opredelenie – denʹ proletit kak mâkina – dokole ne prišel na vas plamennyj gnev Gospodenʹ, dokole ne nastupil dlâ vas denʹ ârosti Gospodnej."],[2,3,"Взыщите Господа, все смиренные земли, исполняющие законы Его; взыщите правду, взыщите смиренномудрие; может быть, вы укроетесь в день гнева Господня.","Vzyŝite Gospoda, vse smirennye zemli, ispolnâûŝie zakony Ego; vzyŝite pravdu, vzyŝite smirennomudrie; možet bytʹ, vy ukroetesʹ v denʹ gneva Gospodnâ."],[2,4,"Ибо Газа будет покинута, и Аскалон опустеет, Азот будет выгнан среди дня, и Екрон искоренится.","Ibo Gaza budet pokinuta, i Askalon opusteet, Azot budet vygnan sredi dnâ, i Ekron iskorenitsâ."],[2,5,"Горе жителям приморской страны, народу Критскому! Слово Господне на вас, Хананеи, земля Филистимская! Я истреблю тебя, и не будет у тебя жителей, –","Gore žitelâm primorskoj strany, narodu Kritskomu! Slovo Gospodne na vas, Hananei, zemlâ Filistimskaâ! Â istreblû tebâ, i ne budet u tebâ žitelej, –"],[2,6,"и будет приморская страна пастушьим овчарником и загоном для скота.","i budet primorskaâ strana pastušʹim ovčarnikom i zagonom dlâ skota."],[2,7,"И достанется этот край остаткам дома Иудина, и будут пасти там, и в домах Аскалона будут вечером отдыхать, ибо Господь Бог их посетит их и возвратит плен их.","I dostanetsâ étot kraj ostatkam doma Iudina, i budut pasti tam, i v domah Askalona budut večerom otdyhatʹ, ibo Gospodʹ Bog ih posetit ih i vozvratit plen ih."],[2,8,"Слышал Я поношение Моава и ругательства сынов Аммоновых, как они издевались над Моим народом и величались на пределах его.","Slyšal Â ponošenie Moava i rugatelʹstva synov Ammonovyh, kak oni izdevalisʹ nad Moim narodom i veličalisʹ na predelah ego."],[2,9,"Посему, живу Я! говорит Господь Саваоф, Бог Израилев: Моав будет как Содом, и сыны Аммона будут, как Гоморра, достоянием крапивы, соляною рытвиною, пустынею навеки; остаток народа Моего возьмет их в добычу, и уцелевшие из людей Моих получат их в наследие.","Posemu, živu Â! govorit Gospodʹ Savaof, Bog Izrailev: Moav budet kak Sodom, i syny Ammona budut, kak Gomorra, dostoâniem krapivy, solânoû rytvinoû, pustyneû naveki; ostatok naroda Moego vozʹmet ih v dobyču, i ucelevšie iz lûdej Moih polučat ih v nasledie."],[2,10,"Это им за высокомерие их, за то, что они издевались и величались над народом Господа Саваофа.","Éto im za vysokomerie ih, za to, čto oni izdevalisʹ i veličalisʹ nad narodom Gospoda Savaofa."],[2,11,"Страшен будет для них Господь, ибо истребит всех богов земли, и Ему будут поклоняться, каждый со своего места, все острова народов.","Strašen budet dlâ nih Gospodʹ, ibo istrebit vseh bogov zemli, i Emu budut poklonâtʹsâ, každyj so svoego mesta, vse ostrova narodov."],[2,12,"И вы, Ефиопляне, избиты будете мечом Моим.","I vy, Efioplâne, izbity budete mečom Moim."],[2,13,"И прострет Он руку Свою на север, и уничтожит Ассура, и обратит Ниневию в развалины, в место сухое, как пустыня,","I prostret On ruku Svoû na sever, i uničtožit Assura, i obratit Nineviû v razvaliny, v mesto suhoe, kak pustynâ,"],[2,14,"и покоиться будут среди нее стада и всякого рода животные; пеликан и еж будут ночевать в резных украшениях ее; голос их будет раздаваться в окнах, разрушение обнаружится на дверных столбах, ибо не станет на них кедровой обшивки.","i pokoitʹsâ budut sredi nee stada i vsâkogo roda životnye; pelikan i ež budut nočevatʹ v reznyh ukrašeniâh ee; golos ih budet razdavatʹsâ v oknah, razrušenie obnaružitsâ na dvernyh stolbah, ibo ne stanet na nih kedrovoj obšivki."],[2,15,"Вот чем будет город торжествующий, живущий беспечно, говорящий в сердце своем: «я, и нет иного, кроме меня». Как он стал развалиною, логовищем для зверей! Всякий, проходя мимо него, посвищет и махнет рукою.","Vot čem budet gorod toržestvuûŝij, živuŝij bespečno, govorâŝij v serdce svoem: «â, i net inogo, krome menâ». Kak on stal razvalinoû, logoviŝem dlâ zverej! Vsâkij, prohodâ mimo nego, posviŝet i mahnet rukoû."],[3,1,"Горе городу нечистому и оскверненному, притеснителю!","Gore gorodu nečistomu i oskvernennomu, pritesnitelû!"],[3,2,"Не слушает голоса, не принимает наставления, на Господа не уповает, к Богу своему не приближается.","Ne slušaet golosa, ne prinimaet nastavleniâ, na Gospoda ne upovaet, k Bogu svoemu ne približaetsâ."],[3,3,"Князья его посреди него – рыкающие львы, судьи его – вечерние волки, не оставляющие до утра ни одной кости.","Knâzʹâ ego posredi nego – rykaûŝie lʹvy, sudʹi ego – večernie volki, ne ostavlâûŝie do utra ni odnoj kosti."],[3,4,"Пророки его – люди легкомысленные, вероломные; священники его оскверняют святыню, попирают закон.","Proroki ego – lûdi legkomyslennye, verolomnye; svâŝenniki ego oskvernâût svâtynû, popiraût zakon."],[3,5,"Господь праведен посреди него, не делает неправды, каждое утро являет суд Свой неизменно; но беззаконник не знает стыда.","Gospodʹ praveden posredi nego, ne delaet nepravdy, každoe utro âvlâet sud Svoj neizmenno; no bezzakonnik ne znaet styda."],[3,6,"Я истребил народы, разрушены твердыни их; пустыми сделал улицы их, так что никто уже не ходит по ним; разорены города их: нет ни одного человека, нет жителей.","Â istrebil narody, razrušeny tverdyni ih; pustymi sdelal ulicy ih, tak čto nikto uže ne hodit po nim; razoreny goroda ih: net ni odnogo čeloveka, net žitelej."],[3,7,"Я говорил: «бойся только Меня, принимай наставление!» и не будет истреблено жилище его, и не постигнет его зло, какое Я постановил о нем; а они прилежно старались портить все свои действия.","Â govoril: «bojsâ tolʹko Menâ, prinimaj nastavlenie!» i ne budet istrebleno žiliŝe ego, i ne postignet ego zlo, kakoe Â postanovil o nem; a oni priležno staralisʹ portitʹ vse svoi dejstviâ."],[3,8,"Итак ждите Меня, говорит Господь, до того дня, когда Я восстану для опустошения, ибо Мною определено собрать народы, созвать царства, чтобы излить на них негодование Мое, всю ярость гнева Моего; ибо огнем ревности Моей пожрана будет вся земля.","Itak ždite Menâ, govorit Gospodʹ, do togo dnâ, kogda Â vosstanu dlâ opustošeniâ, ibo Mnoû opredeleno sobratʹ narody, sozvatʹ carstva, čtoby izlitʹ na nih negodovanie Moe, vsû ârostʹ gneva Moego; ibo ognem revnosti Moej požrana budet vsâ zemlâ."],[3,9,"Тогда опять Я дам народам уста чистые, чтобы все призывали имя Господа и служили Ему единодушно.","Togda opâtʹ Â dam narodam usta čistye, čtoby vse prizyvali imâ Gospoda i služili Emu edinodušno."],[3,10,"Из заречных стран Ефиопии поклонники Мои, дети рассеянных Моих, принесут Мне дары.","Iz zarečnyh stran Efiopii poklonniki Moi, deti rasseânnyh Moih, prinesut Mne dary."],[3,11,"В тот день ты не будешь срамить себя всякими поступками твоими, какими ты грешил против Меня, ибо тогда Я удалю из среды твоей тщеславящихся твоею знатностью, и не будешь более превозноситься на святой горе Моей.","V tot denʹ ty ne budešʹ sramitʹ sebâ vsâkimi postupkami tvoimi, kakimi ty grešil protiv Menâ, ibo togda Â udalû iz sredy tvoej tŝeslavâŝihsâ tvoeû znatnostʹû, i ne budešʹ bolee prevoznositʹsâ na svâtoj gore Moej."],[3,12,"Но оставлю среди тебя народ смиренный и простой, и они будут уповать на имя Господне.","No ostavlû sredi tebâ narod smirennyj i prostoj, i oni budut upovatʹ na imâ Gospodne."],[3,13,"Остатки Израиля не будут делать неправды, не станут говорить лжи, и не найдется в устах их языка коварного, ибо сами будут пастись и покоиться, и никто не потревожит их.","Ostatki Izrailâ ne budut delatʹ nepravdy, ne stanut govoritʹ lži, i ne najdetsâ v ustah ih âzyka kovarnogo, ibo sami budut pastisʹ i pokoitʹsâ, i nikto ne potrevožit ih."],[3,14,"Ликуй, дщерь Сиона! торжествуй, Израиль! веселись и радуйся от всего сердца, дщерь Иерусалима!","Likuj, dŝerʹ Siona! toržestvuj, Izrailʹ! veselisʹ i radujsâ ot vsego serdca, dŝerʹ Ierusalima!"],[3,15,"Отменил Господь приговор над тобою, прогнал врага твоего! Господь, царь Израилев, посреди тебя: уже более не увидишь зла.","Otmenil Gospodʹ prigovor nad toboû, prognal vraga tvoego! Gospodʹ, carʹ Izrailev, posredi tebâ: uže bolee ne uvidišʹ zla."],[3,16,"В тот день скажут Иерусалиму: «не бойся», и Сиону: «да не ослабевают руки твои!»","V tot denʹ skažut Ierusalimu: «ne bojsâ», i Sionu: «da ne oslabevaût ruki tvoi!»"],[3,17,"Господь Бог твой среди тебя, Он силен спасти тебя; возвеселится о тебе радостью, будет милостив по любви Своей, будет торжествовать о тебе с ликованием.","Gospodʹ Bog tvoj sredi tebâ, On silen spasti tebâ; vozveselitsâ o tebe radostʹû, budet milostiv po lûbvi Svoej, budet toržestvovatʹ o tebe s likovaniem."],[3,18,"Сетующих о торжественных празднествах Я соберу: твои они, на них тяготеет поношение.","Setuûŝih o toržestvennyh prazdnestvah Â soberu: tvoi oni, na nih tâgoteet ponošenie."],[3,19,"Вот, Я стесню всех притеснителей твоих в то время и спасу хромлющее, и соберу рассеянное, и приведу их в почет и именитость на всей этой земле поношения их.","Vot, Â stesnû vseh pritesnitelej tvoih v to vremâ i spasu hromlûŝee, i soberu rasseânnoe, i privedu ih v počet i imenitostʹ na vsej étoj zemle ponošeniâ ih."],[3,20,"В то время приведу вас и тогда же соберу вас, ибо сделаю вас именитыми и почетными между всеми народами земли, когда возвращу плен ваш перед глазами вашими, говорит Господь.","V to vremâ privedu vas i togda že soberu vas, ibo sdelaû vas imenitymi i početnymi meždu vsemi narodami zemli, kogda vozvraŝu plen vaš pered glazami vašimi, govorit Gospodʹ."]],"cmn-cuv-hant":[[1,1,"當 猶大王 亞們的兒子 約西亞在位的時候，耶和華的話臨到 希西家的玄孫， 亞瑪利雅的曾孫， 基大利的孫子， 古示的兒子 西番雅。","dāng yóu dà wáng yà men de ér zǐ yuē xī yà zài wèi de shí hòu， yé hé huá de huà lín dào xī xī jiā de xuán sūn， yà mǎ lì yǎ de céng sūn， jī dà lì de sūn zǐ， gǔ shì de ér zǐ xī fān yǎ."],[1,2,"耶和華說： 我必從地上除滅萬類。","yé hé huá shuō： wǒ bì cóng de shàng chú miè wàn lèi."],[1,3,"我必除滅人和牲畜， 與空中的鳥、海裏的魚， 以及絆腳石和惡人； 我必將人從地上剪除。 這是耶和華說的。","wǒ bì chú miè rén hé shēng chù， yǔ kōng zhōng de niǎo, hǎi lǐ de yú， yǐ jí bàn jiǎo shí hé è rén； wǒ bì jiāng rén cóng de shàng jiǎn chú. zhè shì yé hé huá shuō de."],[1,4,"我必伸手攻擊 猶大 和 耶路撒冷的一切居民， 也必從這地方剪除所剩下的 巴力， 並 基瑪林的名和祭司，","wǒ bì shēn shǒu gōng jī yóu dà hé yé lù sā lěng de yī qiè jū mín， yě bì cóng zhè de fāng jiǎn chú suǒ shèng xià de bā lì， bìng jī mǎ lín de míng hé jì sī，"],[1,5,"與那些在房頂上敬拜天上萬象的， 並那些敬拜耶和華指着他起誓， 又指着 瑪勒堪起誓的，","yǔ nà xiē zài fáng dǐng shàng jìng bài tiān shàng wàn xiàng de， bìng nà xiē jìng bài yé hé huá zhǐ zhe tā qǐ shì， yòu zhǐ zhe mǎ lēi kān qǐ shì de，"],[1,6,"與那些轉去不跟從耶和華的， 和不尋求耶和華也不訪問他的。","yǔ nà xiē zhuǎn qù bù gēn cóng yé hé huá de， hé bù xún qiú yé hé huá yě bù fǎng wèn tā de."],[1,7,"你要在主耶和華面前靜默無聲， 因為耶和華的日子快到。 耶和華已經預備祭物， 將他的客分別為聖。","nǐ yào zài zhǔ yé hé huá miàn qián jìng mò wú shēng， yīn wèi yé hé huá de rì zǐ kuài dào. yé hé huá yǐ jīng yù bèi jì wù， jiāng tā de kè fēn bié wèi shèng."],[1,8,"到了我－耶和華獻祭的日子， 必懲罰首領和王子， 並一切穿外邦衣服的。","dào le wǒ－yé hé huá xiàn jì de rì zǐ， bì chéng fá shǒu lǐng hé wáng zǐ， bìng yī qiè chuān wài bāng yī fú de."],[1,9,"到那日，我必懲罰一切跳過門檻、 將強暴和詭詐 得來之物充滿主人房屋的。","dào nà rì， wǒ bì chéng fá yī qiè tiào guò mén kǎn, jiāng qiáng bào hé guǐ zhà dé lái zhī wù chōng mǎn zhǔ rén fáng wū de."],[1,10,"耶和華說：當那日， 從 魚門必發出悲哀的聲音， 從二城發出哀號的聲音， 從山間發出大破裂的響聲。","yé hé huá shuō： dāng nà rì， cóng yú mén bì fā chū bēi āi de shēng yīn， cóng èr chéng fā chū āi hào de shēng yīn， cóng shān jiān fā chū dà pò liè de xiǎng shēng."],[1,11,"瑪革提施的居民哪，你們要哀號， 因為 迦南的商民都滅亡了！ 凡搬運銀子的都被剪除。","mǎ gé tí shī de jū mín nǎ， nǐ men yào āi hào， yīn wèi jiā nán de shāng mín dōu miè wáng le！ fán bān yùn yín zǐ de dōu bèi jiǎn chú."],[1,12,"那時，我必用燈巡查 耶路撒冷； 我必懲罰那些 如酒在渣滓上澄清的； 他們心裏說： 耶和華必不降福，也不降禍。","nà shí， wǒ bì yòng dēng xún chá yé lù sā lěng； wǒ bì chéng fá nà xiē rú jiǔ zài zhā zǐ shàng chéng qīng de； tā men xīn lǐ shuō： yé hé huá bì bù jiàng fú， yě bù jiàng huò."],[1,13,"他們的財寶必成為掠物； 他們的房屋必變為荒場。 他們必建造房屋，卻不得住在其內； 栽種葡萄園，卻不得喝所出的酒。","tā men de cái bǎo bì chéng wèi lüè wù； tā men de fáng wū bì biàn wèi huāng chǎng. tā men bì jiàn zào fáng wū， què bù dé zhù zài qí nèi； zāi zhǒng pú táo yuán， què bù dé hē suǒ chū de jiǔ."],[1,14,"耶和華的大日臨近， 臨近而且甚快， 乃是耶和華日子的風聲； 勇士必痛痛地哭號。","yé hé huá de dà rì lín jìn， lín jìn ér qiě shèn kuài， nǎi shì yé hé huá rì zǐ de fēng shēng； yǒng shì bì tòng tòng de kū hào."],[1,15,"那日是忿怒的日子， 是急難困苦的日子， 是荒廢淒涼的日子， 是黑暗幽冥、密雲烏黑的日子，","nà rì shì fèn nù de rì zǐ， shì jí nán kùn kǔ de rì zǐ， shì huāng fèi qī liáng de rì zǐ， shì hēi àn yōu míng, mì yún wū hēi de rì zǐ，"],[1,16,"是吹角吶喊的日子， 要攻擊堅固城和高大的城樓。","shì chuī jiǎo nà hǎn de rì zǐ， yào gōng jī jiān gù chéng hé gāo dà de chéng lóu."],[1,17,"我必使災禍臨到人身上， 使他們行走如同瞎眼的， 因為得罪了我。 他們的血必倒出如灰塵； 他們的肉必拋棄如糞土。","wǒ bì shǐ zāi huò lín dào rén shēn shàng， shǐ tā men xíng zǒu rú tóng xiā yǎn de， yīn wèi dé zuì le wǒ. tā men de xuè bì dào chū rú huī chén； tā men de ròu bì pāo qì rú fèn tǔ."],[1,18,"當耶和華發怒的日子， 他們的金銀不能救他們； 他的忿怒如火必燒滅全地， 毀滅這地的一切居民，而且大大毀滅。","dāng yé hé huá fā nù de rì zǐ， tā men de jīn yín bù néng jiù tā men； tā de fèn nù rú huǒ bì shāo miè quán de， huǐ miè zhè de de yī qiè jū mín， ér qiě dà dà huǐ miè."],[2,1,"不知羞恥的國民哪，你們應當聚集！ 趁命令沒有發出， 日子過去如 風前的糠， 耶和華的烈怒未臨到你們， 他發怒的日子未到以先， 你們應當聚集前來。","bù zhī xiū chǐ de guó mín nǎ， nǐ men yīng dāng jù jí！ chèn mìng lìng méi yǒu fā chū， rì zǐ guò qù rú fēng qián de kāng， yé hé huá de liè nù wèi lín dào nǐ men， tā fā nù de rì zǐ wèi dào yǐ xiān， nǐ men yīng dāng jù jí qián lái."],[2,3,"世上遵守耶和華典章的謙卑人哪， 你們都當尋求耶和華！ 當尋求公義謙卑， 或者在耶和華發怒的日子可以隱藏起來。","shì shàng zūn shǒu yé hé huá diǎn zhāng de qiān bēi rén nǎ， nǐ men dōu dāng xún qiú yé hé huá！ dāng xún qiú gōng yì qiān bēi， huò zhě zài yé hé huá fā nù de rì zǐ kě yǐ yǐn cáng qǐ lái."],[2,4,"迦薩必致見棄； 亞實基倫必然荒涼。 人在正午必趕出 亞實突的民； 以革倫也被拔出根來。","jiā sà bì zhì jiàn qì； yà shí jī lún bì rán huāng liáng. rén zài zhèng wǔ bì gǎn chū yà shí tū de mín； yǐ gé lún yě bèi bá chū gēn lái."],[2,5,"住沿海之地的 基利提族有禍了！ 迦南、 非利士人之地啊，耶和華的話與你反對， 說：我必毀滅你，以致無人居住。","zhù yán hǎi zhī de de jī lì tí zú yǒu huò le！ jiā nán, fēi lì shì rén zhī de a， yé hé huá de huà yǔ nǐ fǎn duì， shuō： wǒ bì huǐ miè nǐ， yǐ zhì wú rén jū zhù."],[2,6,"沿海之地要變為草場， 其上有牧人的住處和羊群的圈。","yán hǎi zhī de yào biàn wèi cǎo chǎng， qí shàng yǒu mù rén de zhù chù hé yáng qún de quān."],[2,7,"這地必為 猶大家剩下的人所得； 他們必在那裏牧放 群羊， 晚上必躺臥在 亞實基倫的房屋中； 因為耶和華－他們的神必眷顧他們， 使他們被擄的人歸回。","zhè de bì wèi yóu dà jiā shèng xià de rén suǒ dé； tā men bì zài nà lǐ mù fàng qún yáng， wǎn shàng bì tǎng wò zài yà shí jī lún de fáng wū zhōng； yīn wèi yé hé huá－tā men de shén bì juàn gù tā men， shǐ tā men bèi lǔ de rén guī huí."],[2,8,"我聽見 摩押人的毀謗和 亞捫人的辱罵， 就是毀謗我的百姓，自誇自大， 侵犯他們的境界。","wǒ tīng jiàn mó yā rén de huǐ bàng hé yà mén rén de rǔ mà， jiù shì huǐ bàng wǒ de bǎi xìng， zì kuā zì dà， qīn fàn tā men de jìng jiè."],[2,9,"萬軍之耶和華－ 以色列的神說： 我指着我的永生起誓： 摩押必像 所多瑪， 亞捫人必像 蛾摩拉， 都變為刺草、鹽坑、永遠荒廢之地。 我百姓所剩下的必擄掠他們； 我國中所餘剩的必得着他們的地。","wàn jūn zhī yé hé huá－ yǐ sè liè de shén shuō： wǒ zhǐ zhe wǒ de yǒng shēng qǐ shì： mó yā bì xiàng suǒ duō mǎ， yà mén rén bì xiàng é mó lā， dōu biàn wèi cì cǎo, yán kēng, yǒng yuǎn huāng fèi zhī de. wǒ bǎi xìng suǒ shèng xià de bì lǔ lüè tā men； wǒ guó zhōng suǒ yú shèng de bì dé zhe tā men de de."],[2,10,"這事臨到他們是因他們驕傲，自誇自大， 毀謗萬軍之耶和華的百姓。","zhè shì lín dào tā men shì yīn tā men jiāo ào， zì kuā zì dà， huǐ bàng wàn jūn zhī yé hé huá de bǎi xìng."],[2,11,"耶和華必向他們顯可畏之威， 因他必叫世上的諸神瘦弱。 列國海島的居民各在自己的地方敬拜他。","yé hé huá bì xiàng tā men xiǎn kě wèi zhī wēi， yīn tā bì jiào shì shàng de zhū shén shòu ruò. liè guó hǎi dǎo de jū mín gè zài zì jǐ de de fāng jìng bài tā."],[2,12,"古實人哪，你們必被我的刀所殺。","gǔ shí rén nǎ， nǐ men bì bèi wǒ de dāo suǒ shā."],[2,13,"耶和華必伸手攻擊北方，毀滅 亞述， 使 尼尼微荒涼，又乾旱如曠野。","yé hé huá bì shēn shǒu gōng jī běi fāng， huǐ miè yà shù， shǐ ní ní wēi huāng liáng， yòu qián hàn rú kuàng yě."],[2,14,"群畜，就是各國的走獸必臥在其中； 鵜鶘和箭豬要宿在柱頂上。 在窗戶內有鳴叫的聲音； 門檻都必毀壞， 香柏木已經露出。","qún chù， jiù shì gè guó de zǒu shòu bì wò zài qí zhōng； tí hú hé jiàn zhū yào sù zài zhù dǐng shàng. zài chuāng hù nèi yǒu míng jiào de shēng yīn； mén kǎn dōu bì huǐ huài， xiāng bǎi mù yǐ jīng lù chū."],[2,15,"這是素來歡樂安然居住的城， 心裏說：惟有我，除我以外再沒有別的； 現在何竟荒涼成為野獸躺臥之處！ 凡經過的人都必搖手嗤笑她。","zhè shì sù lái huān lè ān rán jū zhù de chéng， xīn lǐ shuō： wéi yǒu wǒ， chú wǒ yǐ wài zài méi yǒu bié de； xiàn zài hé jìng huāng liáng chéng wèi yě shòu tǎng wò zhī chù！ fán jīng guò de rén dōu bì yáo shǒu chī xiào tā."],[3,1,"這悖逆、污穢、欺壓的城有禍了！","zhè bèi nì, wū huì, qī yā de chéng yǒu huò le！"],[3,2,"她不聽從命令，不領受訓誨， 不倚靠耶和華， 不親近她的神。","tā bù tīng cóng mìng lìng， bù lǐng shòu xùn huì， bù yǐ kào yé hé huá， bù qīn jìn tā de shén."],[3,3,"她中間的首領是咆哮的獅子； 她的審判官是晚上的豺狼， 一點 食物也不留到早晨。","tā zhōng jiān de shǒu lǐng shì páo xiào de shī zǐ； tā de shěn pàn guān shì wǎn shàng de chái láng， yī diǎn shí wù yě bù liú dào zǎo chén."],[3,4,"她的先知是虛浮詭詐的人； 她的祭司褻瀆聖所， 強解律法。","tā de xiān zhī shì xū fú guǐ zhà de rén； tā de jì sī xiè dú shèng suǒ， qiáng jiě lǜ fǎ."],[3,5,"耶和華在她中間是公義的， 斷不做非義的事， 每早晨顯明他的公義，無日不然； 只是不義的人不知羞恥。","yé hé huá zài tā zhōng jiān shì gōng yì de， duàn bù zuò fēi yì de shì， měi zǎo chén xiǎn míng tā de gōng yì， wú rì bù rán； zhǐ shì bù yì de rén bù zhī xiū chǐ."],[3,6,"我－ 耶和華已經除滅列國的民； 他們的城樓毀壞。 我使他們的街道荒涼，以致無人經過； 他們的城邑毀滅，以致無人， 也無居民。","wǒ－ yé hé huá yǐ jīng chú miè liè guó de mín； tā men de chéng lóu huǐ huài. wǒ shǐ tā men de jiē dào huāng liáng， yǐ zhì wú rén jīng guò； tā men de chéng yì huǐ miè， yǐ zhì wú rén， yě wú jū mín."],[3,7,"我說：你只要敬畏我，領受訓誨； 如此，你的住處不致照我所擬定的除滅。 只是你們從早起來就在一切事上敗壞自己。","wǒ shuō： nǐ zhǐ yào jìng wèi wǒ， lǐng shòu xùn huì； rú cǐ， nǐ de zhù chù bù zhì zhào wǒ suǒ nǐ dìng de chú miè. zhǐ shì nǐ men cóng zǎo qǐ lái jiù zài yī qiè shì shàng bài huài zì jǐ."],[3,8,"耶和華說：你們要等候我， 直到我興起擄掠的日子； 因為我已定意招聚列國，聚集列邦， 將我的惱怒－就是我的烈怒都傾在她們身上。 我的忿怒如火，必燒滅全地。","yé hé huá shuō： nǐ men yào děng hòu wǒ， zhí dào wǒ xìng qǐ lǔ lüè de rì zǐ； yīn wèi wǒ yǐ dìng yì zhāo jù liè guó， jù jí liè bāng， jiāng wǒ de nǎo nù－jiù shì wǒ de liè nù dōu qīng zài tā men shēn shàng. wǒ de fèn nù rú huǒ， bì shāo miè quán de."],[3,9,"那時，我必使萬民用清潔的言語 好求告 我－耶和華的名， 同心合意地事奉我。","nà shí， wǒ bì shǐ wàn mín yòng qīng jié de yán yǔ hǎo qiú gào wǒ－yé hé huá de míng， tóng xīn hé yì de shì fèng wǒ."],[3,10,"祈禱我的，就是我所分散的民， 必從 古實河外來，給我獻供物。","qí dǎo wǒ de， jiù shì wǒ suǒ fēn sàn de mín， bì cóng gǔ shí hé wài lái， gěi wǒ xiàn gōng wù."],[3,11,"當那日，你必不因你一切得罪我的事自覺羞愧； 因為那時我必從你中間除掉矜誇高傲之輩， 你也不再於我的聖山狂傲。","dāng nà rì， nǐ bì bù yīn nǐ yī qiè dé zuì wǒ de shì zì jué xiū kuì； yīn wèi nà shí wǒ bì cóng nǐ zhōng jiān chú diào jīn kuā gāo ào zhī bèi， nǐ yě bù zài yú wǒ de shèng shān kuáng ào."],[3,12,"我卻要在你中間留下困苦貧寒的民； 他們必投靠我－耶和華的名。","wǒ què yào zài nǐ zhōng jiān liú xià kùn kǔ pín hán de mín； tā men bì tóu kào wǒ－yé hé huá de míng."],[3,13,"以色列所剩下的人必不作罪孽， 不說謊言，口中也沒有詭詐的舌頭； 而且吃喝躺臥，無人驚嚇。","yǐ sè liè suǒ shèng xià de rén bì bù zuò zuì niè， bù shuō huǎng yán， kǒu zhōng yě méi yǒu guǐ zhà de shé tóu； ér qiě chī hē tǎng wò， wú rén jīng xià."],[3,14,"錫安的民哪，應當歌唱！ 以色列啊，應當歡呼！ 耶路撒冷的民哪，應當滿心歡喜快樂！","xī ān de mín nǎ， yīng dāng gē chàng！ yǐ sè liè a， yīng dāng huān hū！ yé lù sā lěng de mín nǎ， yīng dāng mǎn xīn huān xǐ kuài lè！"],[3,15,"耶和華已經除去你的刑罰， 趕出你的仇敵。 以色列的王－耶和華在你中間； 你必不再懼怕災禍。","yé hé huá yǐ jīng chú qù nǐ de xíng fá， gǎn chū nǐ de chóu dí. yǐ sè liè de wáng－yé hé huá zài nǐ zhōng jiān； nǐ bì bù zài jù pà zāi huò."],[3,16,"當那日，必有話向 耶路撒冷說： 不要懼怕！ 錫安哪； 不要手軟！","dāng nà rì， bì yǒu huà xiàng yé lù sā lěng shuō： bù yào jù pà！ xī ān nǎ； bù yào shǒu ruǎn！"],[3,17,"耶和華－你的神是施行拯救、 大有能力的 主。 他在你中間必因你歡欣喜樂， 默然愛你，且因你喜樂而歡呼。","yé hé huá－nǐ de shén shì shī xíng zhěng jiù, dà yǒu néng lì de zhǔ. tā zài nǐ zhōng jiān bì yīn nǐ huān xīn xǐ lè， mò rán ài nǐ， qiě yīn nǐ xǐ lè ér huān hū."],[3,18,"那些屬你、為無大會愁煩、 因你擔當羞辱的，我必聚集他們。","nà xiē shǔ nǐ, wèi wú dà huì chóu fán, yīn nǐ dān dāng xiū rǔ de， wǒ bì jù jí tā men."],[3,19,"那時，我必罰辦一切苦待你的人， 又拯救你瘸腿的，聚集你被趕出的。 那些在全地受羞辱的， 我必使他們得稱讚，有名聲。","nà shí， wǒ bì fá bàn yī qiè kǔ dài nǐ de rén， yòu zhěng jiù nǐ qué tuǐ de， jù jí nǐ bèi gǎn chū de. nà xiē zài quán de shòu xiū rǔ de， wǒ bì shǐ tā men dé chēng zàn， yǒu míng shēng."],[3,20,"那時，我必領你們進來，聚集你們； 我使你們被擄之人歸回的時候， 就必使你們在地上的萬民中有名聲，得稱讚。 這是耶和華說的。","nà shí， wǒ bì lǐng nǐ men jìn lái， jù jí nǐ men； wǒ shǐ nǐ men bèi lǔ zhī rén guī huí de shí hòu， jiù bì shǐ nǐ men zài de shàng de wàn mín zhōng yǒu míng shēng， dé chēng zàn. zhè shì yé hé huá shuō de."]],"arb-vandyck":[[1,1,"كَلِمَةُ ٱلرَّبِّ ٱلَّتِي صَارَتْ إِلَى صَفَنْيَا بْنِ كُوشِي بْنِ جَدَلْيَا بْنِ أَمَرِيَا بْنِ حَزَقِيَّا، فِي أَيَّامِ يُوشِيَّا بْنِ آمُونَ مَلِكِ يَهُوذَا:","kalimaẗu ٱlrãbĩ ٱlãtī ṣārat̊ ại̹lay̱ ṣafan̊yā b̊ni kūsẖī b̊ni jadal̊yā b̊ni ạảmarīā b̊ni ḥazaqīãạ, fī ạảyãạmi yūsẖīãạ b̊ni ậmūna maliki yahūdẖā:"],[1,2,"«نَزْعًا أَنْزَعُ ٱلْكُلَّ عَنْ وَجْهِ ٱلْأَرْضِ، يَقُولُ ٱلرَّبُّ.","«naz̊ʿaⁿạ ạản̊zaʿu ٱl̊kulã ʿan̊ waj̊hi ٱl̊ạảr̊ḍi, yaqūlu ٱlrãbũ."],[1,3,"أَنْزِعُ ٱلْإِنْسَانَ وَٱلْحَيَوَانَ. أَنْزِعُ طُيُورَ ٱلسَّمَاءِ وَسَمَكَ ٱلْبَحْرِ، وَٱلْمَعَاثِرَ مَعَ ٱلْأَشْرَارِ، وَأَقْطَعُ ٱلْإِنْسَانَ عَنْ وَجْهِ ٱلْأَرْضِ، يَقُولُ ٱلرَّبُّ.","ạản̊ziʿu ٱl̊ại̹n̊sāna waٱl̊ḥayawāna. ạản̊ziʿu ṭuyūra ٱlsãmāʾi wasamaka ٱl̊baḥ̊ri, waٱl̊maʿātẖira maʿa ٱl̊ạảsẖ̊rāri, wāảq̊ṭaʿu ٱl̊ại̹n̊sāna ʿan̊ waj̊hi ٱl̊ạảr̊ḍi, yaqūlu ٱlrãbũ."],[1,4,"«وَأَمُدُّ يَدِي عَلَى يَهُوذَا وَعَلَى كُلِّ سُكَّانِ أُورُشَلِيمَ، وَأَقْطَعُ مِنْ هَذَا ٱلْمَكَانِ بَقِيَّةَ ٱلْبَعْلِ، ٱسْمَ ٱلْكَمَارِيمِ، مَعَ ٱلْكَهَنَةِ.","«wāảmudũ yadī ʿalay̱ yahūdẖā waʿalay̱ kulĩ sukãạni ạủwrusẖalīma, wāảq̊ṭaʿu min̊ hadẖā ٱl̊makāni baqīãẗa ٱl̊baʿ̊li, ٱs̊ma ٱl̊kamārīmi, maʿa ٱl̊kahanaẗi."],[1,5,"وَٱلسَّاجِدِينَ عَلَى ٱلسُّطُوحِ لِجُنْدِ ٱلسَّمَاءِ، وَٱلسَّاجِدِينَ ٱلْحَالِفِينَ بِٱلرَّبِّ، وَٱلْحَالِفِينَ بِمَلْكُومَ،","waٱlsãạjidīna ʿalay̱ ٱlsũṭūḥi lijun̊di ٱlsãmāʾi, waٱlsãạjidīna ٱl̊ḥālifīna biٱlrãbĩ, waٱl̊ḥālifīna bimal̊kūma,"],[1,6,"وَٱلْمُرْتَدِّينَ مِنْ وَرَاءِ ٱلرَّبِّ، وَٱلَّذِينَ لَمْ يَطْلُبُوا ٱلرَّبَّ وَلَا سَأَلُوا عَنْهُ.","waٱl̊mur̊tadĩyna min̊ warāʾi ٱlrãbĩ, waٱlãdẖīna lam̊ yaṭ̊lubūạ ٱlrãbã walā sāảlūạ ʿan̊hu."],[1,7,"«اُسْكُتْ قُدَّامَ ٱلسَّيِّدِ ٱلرَّبِّ، لِأَنَّ يَوْمَ ٱلرَّبِّ قَرِيبٌ. لِأَنَّ ٱلرَّبَّ قَدْ أَعَدَّ ذَبِيحَةً. قَدَّسَ مَدْعُوِّيهِ.","«ạus̊kut̊ qudãạma ٱlsãyĩdi ٱlrãbĩ, liạảnã yaẘma ٱlrãbĩ qarībuⁿ. liạảnã ٱlrãbã qad̊ ạảʿadã dẖabīḥaẗaⁿ. qadãsa mad̊ʿūĩyhi."],[1,8,"وَيَكُونُ فِي يَوْمِ ذَبِيحَةِ ٱلرَّبِّ أَنِّي أُعَاقِبُ ٱلرُّؤَسَاءَ وَبَنِي ٱلْمَلِكِ وَجَمِيعَ ٱلّلَابِسِينَ لِبَاسًا غَرِيبًا.","wayakūnu fī yaẘmi dẖabīḥaẗi ٱlrãbĩ ạảnĩy ạủʿāqibu ٱlrũwảsāʾa wabanī ٱl̊maliki wajamīʿa ٱl̃lābisīna libāsaⁿạ gẖarībaⁿạ."],[1,9,"وَفِي ذَلِكَ ٱلْيَوْمِ أُعَاقِبُ كُلَّ ٱلَّذِينَ يَقْفِزُونَ مِنْ فَوْقِ ٱلْعَتَبَةِ، ٱلَّذِينَ يَمْلَأُونَ بَيْتَ سَيِّدِهِمْ ظُلْمًا وَغِشًّا.","wafī dẖalika ٱl̊yaẘmi ạủʿāqibu kulã ٱlãdẖīna yaq̊fizūna min̊ faẘqi ٱl̊ʿatabaẗi, ٱlãdẖīna yam̊lāủwna baẙta sayĩdihim̊ ẓul̊maⁿạ wagẖisẖaⁿ̃ạ."],[1,10,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، صَوْتُ صُرَاخٍ مِنْ بَابِ ٱلسَّمَكِ، وَوَلْوَلَةٌ مِنَ ٱلْقِسْمِ ٱلثَّانِي وَكَسْرٌ عَظِيمٌ مِنَ ٱلْآكَامِ.","wayakūnu fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ṣaẘtu ṣurākẖiⁿ min̊ bābi ٱlsãmaki, wawal̊walaẗuⁿ mina ٱl̊qis̊mi ٱltẖãạnī wakas̊ruⁿ ʿaẓīmuⁿ mina ٱl̊ậkāmi."],[1,11,"وَلْوِلُوا يَا سُكَّانَ مَكْتِيشَ، لِأَنَّ كُلَّ شَعْبِ كَنْعَانَ بَادَ. ٱنْقَطَعَ كُلُّ ٱلْحَامِلِينَ ٱلْفِضَّةَ.","wal̊wilūạ yā sukãạna mak̊tīsẖa, liạảnã kulã sẖaʿ̊bi kan̊ʿāna bāda. ٱn̊qaṭaʿa kulũ ٱl̊ḥāmilīna ٱl̊fiḍãẗa."],[1,12,"وَيَكُونُ فِي ذَلِكَ ٱلْوَقْتِ أَنِّي أُفَتِّشُ أُورُشَلِيمَ بِٱلسُّرُجِ، وَأُعَاقِبُ ٱلرِّجَالَ ٱلْجَامِدِينَ عَلَى دُرْدِيِّهِمِ، ٱلْقَائِلِينَ فِي قُلُوبِهِمْ: إِنَّ ٱلرَّبَّ لَا يُحْسِنُ وَلَا يُسِيءُ.","wayakūnu fī dẖalika ٱl̊waq̊ti ạảnĩy ạủfatĩsẖu ạủwrusẖalīma biٱlsũruji, wāủʿāqibu ٱlrĩjāla ٱl̊jāmidīna ʿalay̱ dur̊dīĩhimi, ٱl̊qāyỉlīna fī qulūbihim̊: ại̹nã ٱlrãbã lā yuḥ̊sinu walā yusīʾu."],[1,13,"فَتَكُونُ ثَرْوَتُهُمْ غَنِيمَةً وَبُيُوتُهُمْ خَرَابًا، وَيَبْنُونَ بُيُوتًا وَلَا يَسْكُنُونَهَا، وَيَغْرِسُونَ كُرُومًا وَلَا يَشْرَبُونَ خَمْرَهَا.","fatakūnu tẖar̊watuhum̊ gẖanīmaẗaⁿ wabuyūtuhum̊ kẖarābaⁿạ, wayab̊nūna buyūtaⁿạ walā yas̊kunūnahā, wayagẖ̊risūna kurūmaⁿạ walā yasẖ̊rabūna kẖam̊rahā."],[1,14,"«قَرِيبٌ يَوْمُ ٱلرَّبِّ ٱلْعَظِيمِ. قَرِيبٌ وَسَرِيعٌ جِدًّا. صَوْتُ يَوْمِ ٱلرّبِّ. يَصْرُخُ حِينَئِذٍ ٱلْجَبَّارُ مُرًّا.","«qarībuⁿ yaẘmu ٱlrãbĩ ٱl̊ʿaẓīmi. qarībuⁿ wasarīʿuⁿ jidaⁿ̃ạ. ṣaẘtu yaẘmi ٱlr̃bĩ. yaṣ̊rukẖu ḥīnayỉdẖiⁿ ٱl̊jabãạru muraⁿ̃ạ."],[1,15,"ذَلِكَ ٱلْيَوْمُ يَوْمُ سَخَطٍ، يَوْمُ ضِيقٍ وَشِدَّةٍ، يَوْمُ خَرَابٍ وَدَمَارٍ، يَوْمُ ظَلَامٍ وَقَتَامٍ، يَوْمُ سَحَابٍ وَضَبَابٍ.","dẖalika ٱl̊yaẘmu yaẘmu sakẖaṭiⁿ, yaẘmu ḍīqiⁿ wasẖidãẗiⁿ, yaẘmu kẖarābiⁿ wadamāriⁿ, yaẘmu ẓalāmiⁿ waqatāmiⁿ, yaẘmu saḥābiⁿ waḍabābiⁿ."],[1,16,"يَوْمُ بُوقٍ وَهُتَافٍ علَى ٱلْمُدُنِ ٱلْمُحَصَّنَةِ وَعَلَى ٱلشُّرُفِ ٱلرَّفِيعَةِ.","yaẘmu būqiⁿ wahutāfiⁿ ʿlay̱ ٱl̊muduni ٱl̊muḥaṣãnaẗi waʿalay̱ ٱlsẖũrufi ٱlrãfīʿaẗi."],[1,17,"وَأُضَايِقُ ٱلنَّاسَ فَيَمْشُونَ كَٱلْعُمْيِ، لِأَنَّهُمْ أَخْطَأُوا إِلَى ٱلرَّبِّ، فَيُسْفَحُ دَمُهُمْ كَٱلتُّرَابِ وَلَحْمُهُمْ كَٱلْجِلَّةِ.","wāủḍāyiqu ٱlnãạsa fayam̊sẖūna kaٱl̊ʿum̊yi, liạảnãhum̊ ạảkẖ̊ṭāủwạ ại̹lay̱ ٱlrãbĩ, fayus̊faḥu damuhum̊ kaٱltũrābi walaḥ̊muhum̊ kaٱl̊jilãẗi."],[1,18,"لَا فِضَّتُهُمْ وَلَا ذَهَبُهُمْ يَسْتَطِيعُ إِنْقَاذَهُمْ في يَوْمِ غَضَبِ ٱلرَّبِّ، بَلْ بِنَارِ غَيْرَتِهِ تُؤْكَلُ ٱلْأَرْضُ كُلُّهَا، لِأَنَّهُ يَصْنَعُ فَنَاءً بَاغِتًا لِكُلِّ سُكَّانِ ٱلْأَرْضِ».","lā fiḍãtuhum̊ walā dẖahabuhum̊ yas̊taṭīʿu ại̹n̊qādẖahum̊ fy yaẘmi gẖaḍabi ٱlrãbĩ, bal̊ bināri gẖaẙratihi tū̊̉kalu ٱl̊ạảr̊ḍu kulũhā, liạảnãhu yaṣ̊naʿu fanāʾaⁿ bāgẖitaⁿạ likulĩ sukãạni ٱl̊ạảr̊ḍi»."],[2,1,"تَجَمَّعِي وَٱجْتَمِعِي يَا أَيَّتُهَا ٱلْأُمَّةُ غَيْرُ ٱلْمُسْتَحِيَةِ.","tajamãʿī waٱj̊tamiʿī yā ạảyãtuhā ٱl̊ạủmãẗu gẖaẙru ٱl̊mus̊taḥīaẗi."],[2,2,"قَبْلَ وِلَادَةِ ٱلْقَضَاءِ. كَٱلْعُصَافَةِ عَبَرَ ٱلْيَوْمُ. قَبْلَ أَنْ يَأْتِيَ عَلَيْكُمْ حُمُوُّ غَضَبِ ٱلرَّبِّ، قَبْلَ أَنْ يَأْتِيَ عَلَيْكُمْ يَوْمُ سَخَطِ ٱلرَّبِّ.","qab̊la wilādaẗi ٱl̊qaḍāʾi. kaٱl̊ʿuṣāfaẗi ʿabara ٱl̊yaẘmu. qab̊la ạản̊ yā̊̉tīa ʿalaẙkum̊ ḥumūũ gẖaḍabi ٱlrãbĩ, qab̊la ạản̊ yā̊̉tīa ʿalaẙkum̊ yaẘmu sakẖaṭi ٱlrãbĩ."],[2,3,"أُطْلُبُوا ٱلرَّبَّ، يَا جَمِيعَ بَائِسِي ٱلْأَرْضِ ٱلَّذِينَ فَعَلُوا حُكْمَهُ. ٱطْلُبُوا ٱلْبِرَّ. ٱطْلُبُوا ٱلتَّوَاضُعَ. لَعَلَّكُمْ تُسْتَرُونَ فِي يَوْمِ سَخَطِ ٱلرَّبِّ.","ạủṭ̊lubūạ ٱlrãbã, yā jamīʿa bāyỉsī ٱl̊ạảr̊ḍi ٱlãdẖīna faʿalūạ ḥuk̊mahu. ٱṭ̊lubūạ ٱl̊birã. ٱṭ̊lubūạ ٱltãwāḍuʿa. laʿalãkum̊ tus̊tarūna fī yaẘmi sakẖaṭi ٱlrãbĩ."],[2,4,"لِأَنَّ غَزَّةَ تَكُونُ مَتْرُوكَةً، وَأَشْقَلُونَ لِلْخَرَابِ. أَشْدُودُ عِنْدَ ٱلظَّهِيرَةِ يَطْرُدُونَهَا، وَعَقْرُونُ تُسْتَأْصَلُ.","liạảnã gẖazãẗa takūnu mat̊rūkaẗaⁿ, wāảsẖ̊qalūna lil̊kẖarābi. ạảsẖ̊dūdu ʿin̊da ٱlẓãhīraẗi yaṭ̊rudūnahā, waʿaq̊rūnu tus̊tā̊̉ṣalu."],[2,5,"وَيْلٌ لِسُكَّانِ سَاحِلِ ٱلْبَحْرِ أُمَّةِ ٱلْكِرِيتِيِّينَ! كَلِمَةُ ٱلرَّبِّ عَلَيْكُمْ: «يَا كَنْعَانُ أَرْضَ ٱلْفِلِسْطِينِيِّينَ، إِنِّي أَخْرِبُكِ بِلَا سَاكِنٍ».","waẙluⁿ lisukãạni sāḥili ٱl̊baḥ̊ri ạủmãẗi ٱl̊kirītīĩyna! kalimaẗu ٱlrãbĩ ʿalaẙkum̊: «yā kan̊ʿānu ạảr̊ḍa ٱl̊filis̊ṭīnīĩyna, ại̹nĩy ạảkẖ̊ribuki bilā sākiniⁿ»."],[2,6,"وَيَكُونُ سَاحِلُ ٱلْبَحْرِ مَرْعًى بِآبَارٍ لِلرُّعَاةِ وَحَظَائِرَ لِلْغَنَمِ.","wayakūnu sāḥilu ٱl̊baḥ̊ri mar̊ʿaⁿy̱ biậbāriⁿ lilrũʿāẗi waḥaẓāyỉra lil̊gẖanami."],[2,7,"وَيَكُونُ ٱلسَّاحِلُ لِبَقِيَّةِ بَيْتِ يَهُوذَا. عَلَيْهِ يَرْعَوْنَ. فِي بُيُوتِ أَشْقَلُونَ عِنْدَ ٱلْمَسَاءِ يَرْبُضُونَ، لِأَنَّ ٱلرَّبَّ إِلَهَهُمْ يَتَعَهَّدُهُمْ وَيَرُدُّ سَبْيَهُمْ.","wayakūnu ٱlsãạḥilu libaqīãẗi baẙti yahūdẖā. ʿalaẙhi yar̊ʿaẘna. fī buyūti ạảsẖ̊qalūna ʿin̊da ٱl̊masāʾi yar̊buḍūna, liạảnã ٱlrãbã ại̹lahahum̊ yataʿahãduhum̊ wayarudũ sab̊yahum̊."],[2,8,"«قَدْ سَمِعْتُ تَعْيِيرَ مُوآبَ وَتَجَادِيفَ بَنِي عَمُّونَ ٱلَّتِي بِهَا عَيَّرُوا شَعْبِي، وَتَعَظَّمُوا عَلَى تُخُمِهِمْ.","«qad̊ samiʿ̊tu taʿ̊yīra mūậba watajādīfa banī ʿamũwna ٱlãtī bihā ʿayãrūạ sẖaʿ̊bī, wataʿaẓãmūạ ʿalay̱ tukẖumihim̊."],[2,9,"فَلِذَلِكَ حَيٌّ أَنَا، يَقُولُ رَبُّ ٱلْجُنُودِ إِلَهُ إِسْرَائِيلَ، إِنَّ مُوآبَ تَكُونُ كَسَدُومَ وَبَنِي عَمُّونَ كَعَمُورَةَ، مِلْكَ ٱلْقَرِيصِ، وَحُفْرَةَ مِلْحٍ، وَخَرَابًا إِلَى ٱلْأَبَدِ. تَنْهَبُهُمْ بَقِيَّةُ شَعْبِي، وَبَقِيَّةُ أُمَّتِي تَمْتَلِكُهُمْ».","falidẖalika ḥayuⁿ̃ ạảnā, yaqūlu rabũ ٱl̊junūdi ại̹lahu ại̹s̊rāyỉyla, ại̹nã mūậba takūnu kasadūma wabanī ʿamũwna kaʿamūraẗa, mil̊ka ٱl̊qarīṣi, waḥuf̊raẗa mil̊ḥiⁿ, wakẖarābaⁿạ ại̹lay̱ ٱl̊ạảbadi. tan̊habuhum̊ baqīãẗu sẖaʿ̊bī, wabaqīãẗu ạủmãtī tam̊talikuhum̊»."],[2,10,"هَذَا لَهُمْ عِوَضُ تَكَبُّرِهِمْ، لِأَنَّهُمْ عَيَّرُوا وَتَعَظَّمُوا عَلَى شَعْبِ رَبِّ ٱلْجُنُودِ.","hadẖā lahum̊ ʿiwaḍu takabũrihim̊, liạảnãhum̊ ʿayãrūạ wataʿaẓãmūạ ʿalay̱ sẖaʿ̊bi rabĩ ٱl̊junūdi."],[2,11,"ٱلرَّبُّ مُخِيفٌ إِلَيْهِمْ، لِأَنَّهُ يُهْزِلُ جَمِيعَ آلِهَةِ ٱلْأَرْضِ، فَسَيَسْجُدُ لَهُ ٱلنَّاسُ، كُلُّ وَاحِدٍ مِنْ مَكَانِهِ، كُلُّ جَزَائِرِ ٱلْأُمَمِ.","ٱlrãbũ mukẖīfuⁿ ại̹laẙhim̊, liạảnãhu yuh̊zilu jamīʿa ậlihaẗi ٱl̊ạảr̊ḍi, fasayas̊judu lahu ٱlnãạsu, kulũ wāḥidiⁿ min̊ makānihi, kulũ jazāyỉri ٱl̊ạủmami."],[2,12,"«وَأَنْتُمْ يَا أَيُّهَا ٱلْكُوشِيُّونَ. قَتْلَى سَيْفِي هُمْ».","«wāản̊tum̊ yā ạảyũhā ٱl̊kūsẖīũwna. qat̊lay̱ saẙfī hum̊»."],[2,13,"وَيَمُدُّ يَدَهُ عَلَى ٱلشِّمَالِ وَيُبِيدُ أَشُّورَ، وَيَجْعَلُ نِينَوَى خَرَابًا يَابِسَةً كَٱلْقَفْرِ.","wayamudũ yadahu ʿalay̱ ٱlsẖĩmāli wayubīdu ạảsẖũwra, wayaj̊ʿalu nīnaway̱ kẖarābaⁿạ yābisaẗaⁿ kaٱl̊qaf̊ri."],[2,14,"فَتَرْبُضُ فِي وَسَطِهَا ٱلْقُطْعَانُ، كُلُّ طَوَائِفِ ٱلْحَيَوَانِ. اَلْقُوقُ أَيْضًا وَٱلْقُنْفُذُ يَأْوِيَانِ إِلَى تِيجَانِ عُمُدِهَا. صَوْتٌ يَنْعِبُ فِي ٱلْكُوَى. خَرَابٌ عَلَى ٱلْأَعْتَابِ. لِأَنَّهُ قَدْ تَعَرَّى أَرْزِيُّهَا.","fatar̊buḍu fī wasaṭihā ٱl̊quṭ̊ʿānu, kulũ ṭawāyỉfi ٱl̊ḥayawāni. ạal̊qūqu ạảẙḍaⁿạ waٱl̊qun̊fudẖu yā̊̉wīāni ại̹lay̱ tījāni ʿumudihā. ṣaẘtuⁿ yan̊ʿibu fī ٱl̊kūay̱. kẖarābuⁿ ʿalay̱ ٱl̊ạảʿ̊tābi. liạảnãhu qad̊ taʿarãy̱ ạảr̊zīũhā."],[2,15,"هَذِهِ هِيَ ٱلْمَدِينَةُ ٱلْمُبْتَهِجَةُ ٱلسَّاكِنَةُ مُطْمَئِنَّةً، ٱلْقَائِلَةُ فِي قَلْبِهَا: «أَنَا وَلَيْسَ غَيْرِي». كَيْفَ صَارَتْ خَرَابًا، مَرْبِضًا لِلْحَيَوَانِ! كُلُّ عَابِرٍ بِهَا يَصْفِرُ وَيَهُزُّ يَدَهُ.","hadẖihi hīa ٱl̊madīnaẗu ٱl̊mub̊tahijaẗu ٱlsãạkinaẗu muṭ̊mayỉnãẗaⁿ, ٱl̊qāyỉlaẗu fī qal̊bihā: «ạảnā walaẙsa gẖaẙrī». kaẙfa ṣārat̊ kẖarābaⁿạ, mar̊biḍaⁿạ lil̊ḥayawāni! kulũ ʿābiriⁿ bihā yaṣ̊firu wayahuzũ yadahu."],[3,1,"وَيْلٌ لِلْمُتَمَرِّدَةِ ٱلْمُنَجَّسَةِ، ٱلْمَدِينَةِ ٱلْجَائِرَةِ!","waẙluⁿ lil̊mutamarĩdaẗi ٱl̊munajãsaẗi, ٱl̊madīnaẗi ٱl̊jāyỉraẗi!"],[3,2,"لَمْ تَسْمَعِ ٱلصَّوْتَ. لَمْ تَقْبَلِ ٱلتَّأْدِيبَ. لَمْ تَتَّكِلْ عَلَى ٱلرَّبِّ. لَمْ تَتَقَرَّبْ إِلَى إِلَهِهَا.","lam̊ tas̊maʿi ٱlṣãẘta. lam̊ taq̊bali ٱltãạ̊̉dība. lam̊ tatãkil̊ ʿalay̱ ٱlrãbĩ. lam̊ tataqarãb̊ ại̹lay̱ ại̹lahihā."],[3,3,"رُؤَسَاؤُهَا فِي وَسَطِهَا أُسُودٌ زَائِرَةٌ. قُضَاتُهَا ذِئَابُ مَسَاءٍ لَا يُبْقُونَ شَيْئًا إِلَى ٱلصَّبَاحِ.","rūảsāwủhā fī wasaṭihā ạủsūduⁿ zāyỉraẗuⁿ. quḍātuhā dẖīảạbu masāʾiⁿ lā yub̊qūna sẖaẙyaⁿ̉ạ ại̹lay̱ ٱlṣãbāḥi."],[3,4,"أَنْبِيَاؤُهَا مُتَفَاخِرُونَ أَهْلُ غُدْرَاتٍ. كَهَنَتُهَا نَجَّسُوا ٱلْقُدْسَ، خَالَفُوا ٱلشَّرِيعَةَ.","ạản̊bīāwủhā mutafākẖirūna ạảh̊lu gẖud̊rātiⁿ. kahanatuhā najãsūạ ٱl̊qud̊sa, kẖālafūạ ٱlsẖãrīʿaẗa."],[3,5,"اَلرَّبُّ عَادِلٌ فِي وَسَطِهَا لَا يَفْعَلُ ظُلْمًا. غَدَاةً غَدَاةً يُبْرِزُ حُكْمَهُ إِلَى ٱلنُّورِ. لَا يَتَعَذَّرُ. أَمَّا ٱلظَّالِمُ فَلَا يَعْرِفُ ٱلْخِزْيَ.","ạalrãbũ ʿādiluⁿ fī wasaṭihā lā yaf̊ʿalu ẓul̊maⁿạ. gẖadāẗaⁿ gẖadāẗaⁿ yub̊rizu ḥuk̊mahu ại̹lay̱ ٱlnũwri. lā yataʿadẖãru. ạảmãạ ٱlẓãạlimu falā yaʿ̊rifu ٱl̊kẖiz̊ya."],[3,6,"«قَطَعْتُ أُمَمًا، خَرَّبْتُ شُرُفَاتِهِمْ، أَقْفَرْتُ أَسْوَاقَهُمْ بِلَا عَابِرٍ. دُمِّرَتْ مُدُنُهُمْ بِلَا إِنْسَانٍ، بِغَيْرِ سَاكِنٍ.","«qaṭaʿ̊tu ạủmamaⁿạ, kẖarãb̊tu sẖurufātihim̊, ạảq̊far̊tu ạảs̊wāqahum̊ bilā ʿābiriⁿ. dumĩrat̊ mudunuhum̊ bilā ại̹n̊sāniⁿ, bigẖaẙri sākiniⁿ."],[3,7,"فَقُلْتُ: إِنَّكِ لِتَخْشَيْنَنِي، تَقْبَلِينَ ٱلتَّأْدِيبَ. فَلَا يَنْقَطِعُ مَسْكَنُهَا حَسَبَ كُلِّ مَا عَيَّنْتُهُ عَلَيْهَا. لَكِنْ بَكَّرُوا وَأَفْسَدُوا جَمِيعَ أَعْمَالِهِمْ.","faqul̊tu: ại̹nãki litakẖ̊sẖaẙnanī, taq̊balīna ٱltãạ̊̉dība. falā yan̊qaṭiʿu mas̊kanuhā ḥasaba kulĩ mā ʿayãn̊tuhu ʿalaẙhā. lakin̊ bakãrūạ wāảf̊sadūạ jamīʿa ạảʿ̊mālihim̊."],[3,8,"«لِذَلِكَ فَٱنْتَظِرُونِي، يَقُولُ ٱلرَّبُّ، إِلَى يَوْمِ أَقُومُ إِلَى ٱلسَّلْبِ، لِأَنَّ حُكْمِي هُوَ بِجَمْعِ ٱلْأُمَمِ وَحَشْرِ ٱلْمَمَالِكِ، لِأَصُبَّ عَلَيْهِمْ سَخَطِي، كُلَّ حُمُوِّ غَضَبِي. لِأَنَّهُ بِنَارِ غَيْرَتِي تُؤْكَلُ كُلُّ ٱلْأَرْضِ.","«lidẖalika faٱn̊taẓirūnī, yaqūlu ٱlrãbũ, ại̹lay̱ yaẘmi ạảqūmu ại̹lay̱ ٱlsãl̊bi, liạảnã ḥuk̊mī hūa bijam̊ʿi ٱl̊ạủmami waḥasẖ̊ri ٱl̊mamāliki, liạảṣubã ʿalaẙhim̊ sakẖaṭī, kulã ḥumūĩ gẖaḍabī. liạảnãhu bināri gẖaẙratī tū̊̉kalu kulũ ٱl̊ạảr̊ḍi."],[3,9,"لِأَنِّي حِينَئِذٍ أُحَوِّلُ ٱلشُّعُوبَ إِلَى شَفَةٍ نَقِيَّةٍ، لِيَدْعُوا كُلُّهُمْ بِٱسْمِ ٱلرَّبِّ، لِيَعْبُدُوهُ بِكَتِفٍ وَاحِدَةٍ.","liạảnĩy ḥīnayỉdẖiⁿ ạủḥawĩlu ٱlsẖũʿūba ại̹lay̱ sẖafaẗiⁿ naqīãẗiⁿ, līad̊ʿūạ kulũhum̊ biٱs̊mi ٱlrãbĩ, līaʿ̊budūhu bikatifiⁿ wāḥidaẗiⁿ."],[3,10,"مِنْ عَبْرِ أَنْهَارِ كُوشٍ ٱلْمُتَضَرِّعُونَ إِلَيَّ، مُتَبَدِّدِيَّ، يُقَدِّمُونَ تَقْدِمَتِي.","min̊ ʿab̊ri ạản̊hāri kūsẖiⁿ ٱl̊mutaḍarĩʿūna ại̹layã, mutabadĩdīã, yuqadĩmūna taq̊dimatī."],[3,11,"فِي ذَلِكَ ٱلْيَوْمِ لَا تَخْزَيْنَ مِنْ كُلِّ أَعْمَالِكِ ٱلَّتِي تَعَدَّيْتِ بِهَا عَلَيَّ. لِأَنِّي حِينَئِذٍ أَنْزِعُ مِنْ وَسَطِكِ مُبْتَهِجِي كِبْرِيَائِكِ، وَلَنْ تَعُودِي بَعْدُ إِلَى ٱلتَّكَبُّرِ فِي جَبَلِ قُدْسِي.","fī dẖalika ٱl̊yaẘmi lā takẖ̊zaẙna min̊ kulĩ ạảʿ̊māliki ٱlãtī taʿadãẙti bihā ʿalayã. liạảnĩy ḥīnayỉdẖiⁿ ạản̊ziʿu min̊ wasaṭiki mub̊tahijī kib̊rīāyỉki, walan̊ taʿūdī baʿ̊du ại̹lay̱ ٱltãkabũri fī jabali qud̊sī."],[3,12,"وَأُبْقِي فِي وَسَطِكِ شَعْبًا بَائِسًا وَمِسْكِينًا، فَيَتَوَكَّلُونَ عَلَى ٱسْمِ ٱلرَّبِّ.","wāủb̊qī fī wasaṭiki sẖaʿ̊baⁿạ bāyỉsaⁿạ wamis̊kīnaⁿạ, fayatawakãlūna ʿalay̱ ٱs̊mi ٱlrãbĩ."],[3,13,"بَقِيَّةُ إِسْرَائِيلَ لَا يَفْعَلُونَ إِثْمًا، وَلَا يَتَكَلَّمُونَ بِٱلْكَذِبِ، وَلَا يُوجَدُ فِي أَفْوَاهِهِمْ لِسَانُ غِشٍّ، لِأَنَّهُمْ يَرْعَوْنَ وَيَرْبُضُونَ وَلَا مُخِيفَ».","baqīãẗu ại̹s̊rāyỉyla lā yaf̊ʿalūna ại̹tẖ̊maⁿạ, walā yatakalãmūna biٱl̊kadẖibi, walā yūjadu fī ạảf̊wāhihim̊ lisānu gẖisẖiⁿ̃, liạảnãhum̊ yar̊ʿaẘna wayar̊buḍūna walā mukẖīfa»."],[3,14,"تَرَنَّمِي يَا ٱبْنَةَ صِهْيَوْنَ! ٱهْتُفْ يَا إِسْرَائِيلُ! ٱفْرَحِي وَٱبْتَهِجِي بِكُلِّ قَلْبِكِ يَا ٱبْنَةَ أُورُشَلِيمَ!","taranãmī yā ٱb̊naẗa ṣih̊yaẘna! ٱh̊tuf̊ yā ại̹s̊rāyỉylu! ٱf̊raḥī waٱb̊tahijī bikulĩ qal̊biki yā ٱb̊naẗa ạủwrusẖalīma!"],[3,15,"قَدْ نَزَعَ ٱلرَّبُّ ٱلْأَقْضِيَةَ عَلَيْكِ، أَزَالَ عَدُوَّكِ. مَلِكُ إِسْرَائِيلَ ٱلرَّبُّ فِي وَسَطِكِ. لَا تَنْظُرِينَ بَعْدُ شَرًّا.","qad̊ nazaʿa ٱlrãbũ ٱl̊ạảq̊ḍīaẗa ʿalaẙki, ạảzāla ʿadūãki. maliku ại̹s̊rāyỉyla ٱlrãbũ fī wasaṭiki. lā tan̊ẓurīna baʿ̊du sẖaraⁿ̃ạ."],[3,16,"فِي ذَلِكَ ٱلْيَوْمِ يُقَالُ لِأُورُشَلِيمَ: «لَا تَخَافِي يَا صِهْيَوْنُ. لَا تَرْتَخِ يَدَاكِ.","fī dẖalika ٱl̊yaẘmi yuqālu liạủwrusẖalīma: «lā takẖāfī yā ṣih̊yaẘnu. lā tar̊takẖi yadāki."],[3,17,"ٱلرَّبُّ إِلَهُكِ فِي وَسَطِكِ جَبَّارٌ. يُخَلِّصُ. يَبْتَهِجُ بِكِ فَرَحًا. يَسْكُتُ فِي مَحَبَّتِهِ. يَبْتَهِجُ بِكِ بِتَرَنُّمٍ».","ٱlrãbũ ại̹lahuki fī wasaṭiki jabãạruⁿ. yukẖalĩṣu. yab̊tahiju biki faraḥaⁿạ. yas̊kutu fī maḥabãtihi. yab̊tahiju biki bitaranũmiⁿ»."],[3,18,"«أَجْمَعُ ٱلْمَحْزُونِينَ عَلَى ٱلْمَوْسِمِ. كَانُوا مِنْكِ. حَامِلِينَ عَلَيْهَا ٱلْعَارَ.","«ạảj̊maʿu ٱl̊maḥ̊zūnīna ʿalay̱ ٱl̊maẘsimi. kānūạ min̊ki. ḥāmilīna ʿalaẙhā ٱl̊ʿāra."],[3,19,"هَأَنَذَا فِي ذَلِكَ ٱلْيَوْمِ أُعَامِلُ كُلَّ مُذَلِّلِيكِ، وَأُخَلِّصُ ٱلظَّالِعَةَ، وَأَجْمَعُ ٱلْمَنْفِيَّةَ، وَأَجْعَلُهُمْ تَسْبِيحَةً وَٱسْمًا فِي كُلِّ أَرْضِ خِزْيِهِمْ،","hāảnadẖā fī dẖalika ٱl̊yaẘmi ạủʿāmilu kulã mudẖalĩlīki, wāủkẖalĩṣu ٱlẓãạliʿaẗa, wāảj̊maʿu ٱl̊man̊fīãẗa, wāảj̊ʿaluhum̊ tas̊bīḥaẗaⁿ waٱs̊maⁿạ fī kulĩ ạảr̊ḍi kẖiz̊yihim̊,"],[3,20,"فِي ٱلْوَقْتِ ٱلَّذِي فِيهِ آتِي بِكُمْ وَفِي وَقْتِ جَمْعِي إِيَّاكُمْ. لِأَنِّي أُصَيِّرُكُمُ ٱسْمًا وَتَسْبِيحَةً فِي شُعُوبِ ٱلْأَرْضِ كُلِّهَا، حِينَ أَرُدُّ مَسْبِيِّيكُمْ قُدَّامَ أَعْيُنِكُمْ، قَالَ ٱلرَّبُّ».","fī ٱl̊waq̊ti ٱlãdẖī fīhi ậtī bikum̊ wafī waq̊ti jam̊ʿī ại̹yãạkum̊. liạảnĩy ạủṣayĩrukumu ٱs̊maⁿạ watas̊bīḥaẗaⁿ fī sẖuʿūbi ٱl̊ạảr̊ḍi kulĩhā, ḥīna ạảrudũ mas̊bīĩykum̊ qudãạma ạảʿ̊yunikum̊, qāla ٱlrãbũ»."]],"bis-obbr":[[1,1,"Ol tok we i stap long buk ya, Hae God i givim long Profet Sefanaea, long taem ya we King Josaea, we papa blong hem King Amon, hem i king long Juda.* Profet ya i wan laen blong King Hesekia ya bifo. King Hesekia ya i papa blong Amaria, mo Amaria i papa blong Gedalia, mo Gedalia i papa blong Kusi, mo Kusi i papa blong Profet Sefanaea.","Ol tok we i stap long buk ya, Hae God i givim long Profet Sefanaea, long taem ya we King Josaea, we papa blong hem King Amon, hem i king long Juda.* Profet ya i wan laen blong King Hesekia ya bifo. King Hesekia ya i papa blong Amaria, mo Amaria i papa blong Gedalia, mo Gedalia i papa blong Kusi, mo Kusi i papa blong Profet Sefanaea."],[1,2,"Nao Profet Sefanaea i talemaot we Hae God i talem se, “!Ol man Jerusalem,* mo ol man Juda*! Olgeta samting we i stap long wol ya, mi bambae mi spolem olgeta evriwan.","Nao Profet Sefanaea i talemaot we Hae God i talem se, “!Ol man Jerusalem,* mo ol man Juda*! Olgeta samting we i stap long wol ya, mi bambae mi spolem olgeta evriwan."],[1,3,"Ol man mo ol anamol, mo ol pijin, mo ol fis, mi bambae mi kilim olgeta evriwan oli ded. Bambae mi mekem ol man nogud oli foldaon. Mi bambae mi kilim olgeta man, we bambae i no moa gat wan i stap. Mi mi Hae God, mo hemia tok blong mi.","Ol man mo ol anamol, mo ol pijin, mo ol fis, mi bambae mi kilim olgeta evriwan oli ded. Bambae mi mekem ol man nogud oli foldaon. Mi bambae mi kilim olgeta man, we bambae i no moa gat wan i stap. Mi mi Hae God, mo hemia tok blong mi."],[1,4,"“Mi bambae mi panisim yufala evriwan we i stap long Jerusalem, mo long ol narafala ples long Juda. Fasin ya blong mekem wosip long god ya Bal,* mi bambae mi sakemaot, mo ol pris blong hem, nem blong olgeta bambae i lus olgeta, man i no moa save tingbaot olgeta bakegen.","“Mi bambae mi panisim yufala evriwan we i stap long Jerusalem, mo long ol narafala ples long Juda. Fasin ya blong mekem wosip long god ya Bal,* mi bambae mi sakemaot, mo ol pris blong hem, nem blong olgeta bambae i lus olgeta, man i no moa save tingbaot olgeta bakegen."],[1,5,"Ol man we oli stap go antap long ruf* blong ol haos blong olgeta, blong mekem wosip long san, mo mun, mo ol sta, be bambae mi kilim olgeta evriwan i ded. Mo olgeta we oli stap mekem wosip long mi, mo oli stap talemaot long mi, se tingting blong olgeta i stap strong long mi, be long semtaem oli stap yusum nem blong god ya Molek blong mekem promes blong olgeta i stanap, olgeta tu, bambae mi kilim olgeta evriwan i ded.","Ol man we oli stap go antap long ruf* blong ol haos blong olgeta, blong mekem wosip long san, mo mun, mo ol sta, be bambae mi kilim olgeta evriwan i ded. Mo olgeta we oli stap mekem wosip long mi, mo oli stap talemaot long mi, se tingting blong olgeta i stap strong long mi, be long semtaem oli stap yusum nem blong god ya Molek blong mekem promes blong olgeta i stanap, olgeta tu, bambae mi kilim olgeta evriwan i ded."],[1,6,"Mo olgeta ya we oli tanem baksaed long mi, oli no moa biaen long mi, mo oli no moa kam long mi blong askem long mi blong mi lidim olgeta, bambae mi kilim olgeta ya evriwan i ded.”","Mo olgeta ya we oli tanem baksaed long mi, oli no moa biaen long mi, mo oli no moa kam long mi blong askem long mi blong mi lidim olgeta, bambae mi kilim olgeta ya evriwan i ded.”"],[1,7,"Nao profet i talem se, “Dei ya we Hae God bambae i jajem olgeta man long hem i stap kam klosap nao. I moa gud yufala i kam, yufala i stap kwaet long fes blong hem. Hem i rere finis blong kilim yufala ol man blong hem, olsem we man i kilim sipsip blong mekem sakrefaes. Mo hem i singaot ol enemi blong yumi finis blong oli kam flatemgud kantri blong yumi.","Nao profet i talem se, “Dei ya we Hae God bambae i jajem olgeta man long hem i stap kam klosap nao. I moa gud yufala i kam, yufala i stap kwaet long fes blong hem. Hem i rere finis blong kilim yufala ol man blong hem, olsem we man i kilim sipsip blong mekem sakrefaes. Mo hem i singaot ol enemi blong yumi finis blong oli kam flatemgud kantri blong yumi."],[1,8,"Hem i talem se, ‘Long dei ya blong kilim man, ol haeman blong king, mo ol pikinini blong hem, mo olgeta we oli stap folem ol kastom blong ol narafala kantri, bambae mi mi panisim olgeta evriwan.","Hem i talem se, ‘Long dei ya blong kilim man, ol haeman blong king, mo ol pikinini blong hem, mo olgeta we oli stap folem ol kastom blong ol narafala kantri, bambae mi mi panisim olgeta evriwan."],[1,9,"Olgeta we oli stap folem fasin blong mekem wosip blong ol hiten man, mo oli stap stil, mo oli stap kilim man i ded, blong fulumapgud haos blong masta blong olgeta long ol samting we oli stilim, be olgeta ya evriwan bambae mi panisim olgeta.","Olgeta we oli stap folem fasin blong mekem wosip blong ol hiten man, mo oli stap stil, mo oli stap kilim man i ded, blong fulumapgud haos blong masta blong olgeta long ol samting we oli stilim, be olgeta ya evriwan bambae mi panisim olgeta."],[1,10,"“ ‘Long dei ya, bambae yufala i save harem noes blong ol man we oli krae long Jerusalem, long doa ya we nem blong hem “Doa blong Fis”. Mo long niufala haf blong taon ya, bambae yufala i save harem ol man oli stap krae, mo bambae yufala i harem ol bigfala noes blong ol samting we oli stap folfoldaon antap long ol hil.","“ ‘Long dei ya, bambae yufala i save harem noes blong ol man we oli krae long Jerusalem, long doa ya we nem blong hem “Doa blong Fis”. Mo long niufala haf blong taon ya, bambae yufala i save harem ol man oli stap krae, mo bambae yufala i harem ol bigfala noes blong ol samting we oli stap folfoldaon antap long ol hil."],[1,11,"Mo yufala we i stap long haf blong taon ya daon, we i ples blong wokem bisnes, taem yufala i harem ol samting ya, bambae yufala i krae bigwan. Bambae yufala i krae, from we ol bisnesman blong yufala bambae oli ded evriwan.","Mo yufala we i stap long haf blong taon ya daon, we i ples blong wokem bisnes, taem yufala i harem ol samting ya, bambae yufala i krae bigwan. Bambae yufala i krae, from we ol bisnesman blong yufala bambae oli ded evriwan."],[1,12,"“ ‘Long taem ya, bambae mi tekem wan laet, nao mi go lukaot ol man long Jerusalem. Mi bambae mi panisim olgeta ya we oli ting se oli no sot long wan samting nating, mo oli save mekem evri samting, oli no nidim man blong givhan long olgeta. Oltaem oli stap talem se, “Hae God i no save mekem wan samting we i gud long yumi, mo hem i no save mekem wan samting we i nogud long yumi tu.”","“ ‘Long taem ya, bambae mi tekem wan laet, nao mi go lukaot ol man long Jerusalem. Mi bambae mi panisim olgeta ya we oli ting se oli no sot long wan samting nating, mo oli save mekem evri samting, oli no nidim man blong givhan long olgeta. Oltaem oli stap talem se, “Hae God i no save mekem wan samting we i gud long yumi, mo hem i no save mekem wan samting we i nogud long yumi tu.”"],[1,13,"Ol man olsem, bambae mi spolem ol haos blong olgeta, mo bambae mi tekemaot olting blong olgeta. Ol haos blong olgeta we oli stap wok long hem yet, neva bambae oli save slip long hem. Mo ol grep* blong olgeta we oli stap planem, be neva bambae oli save dring waen we i kamaot long hem.’ ”","Ol man olsem, bambae mi spolem ol haos blong olgeta, mo bambae mi tekemaot olting blong olgeta. Ol haos blong olgeta we oli stap wok long hem yet, neva bambae oli save slip long hem. Mo ol grep* blong olgeta we oli stap planem, be neva bambae oli save dring waen we i kamaot long hem.’ ”"],[1,14,"Nao profet i talem se, “Bigfala Dei ya blong Hae God i kam klosap finis. I no longtaem, bambae i kamtru. Dei ya i nogud we i nogud. Nating we i gat ol soldia we oli save faet, be long dei ya, bambae oli krae, from we tingting blong olgeta bambae i foldaon olgeta.","Nao profet i talem se, “Bigfala Dei ya blong Hae God i kam klosap finis. I no longtaem, bambae i kamtru. Dei ya i nogud we i nogud. Nating we i gat ol soldia we oli save faet, be long dei ya, bambae oli krae, from we tingting blong olgeta bambae i foldaon olgeta."],[1,15,"Dei ya, bambae i dei blong kros blong Hae God, mo i dei blong man i trabol, i harem nogud. Long dei ya, Hae God bambae i spolem olgeta samting. Long taem ya, bambae long dei nomo, be ples bambae i kam tudak olgeta, mo klaod we i blak we i blak bambae i kavremap olgeta ples.","Dei ya, bambae i dei blong kros blong Hae God, mo i dei blong man i trabol, i harem nogud. Long dei ya, Hae God bambae i spolem olgeta samting. Long taem ya, bambae long dei nomo, be ples bambae i kam tudak olgeta, mo klaod we i blak we i blak bambae i kavremap olgeta ples."],[1,16,"Long dei ya, bambae i gat noes blong ol pupu blong talemaot we faet i stap kam, mo noes blong ol soldia, we oli stap singsingaot blong kam faet agens long ol man blong ol bigfala taon we ol stonwol i goraon long olgeta, mo agens long ol man long ol wajhaos* we oli hae we i hae.”","Long dei ya, bambae i gat noes blong ol pupu blong talemaot we faet i stap kam, mo noes blong ol soldia, we oli stap singsingaot blong kam faet agens long ol man blong ol bigfala taon we ol stonwol i goraon long olgeta, mo agens long ol man long ol wajhaos* we oli hae we i hae.”"],[1,17,"Mo profet i talemaot we Hae God i talem se, “Bambae mi mi letem bigfala trabol i kam kasem olgeta man, mo trabol ya bambae i mekem olgeta oli stap wokbaot olsem man we i blaen. Naoia bambae mi kilim olgeta, from we oli stap mekem sin agens long mi. Bambae blad blong olgeta i ron bigwan olsem wota. Ol dedbodi blong olgeta bambae i stap roten olbaot long evri ples.”","Mo profet i talemaot we Hae God i talem se, “Bambae mi mi letem bigfala trabol i kam kasem olgeta man, mo trabol ya bambae i mekem olgeta oli stap wokbaot olsem man we i blaen. Naoia bambae mi kilim olgeta, from we oli stap mekem sin agens long mi. Bambae blad blong olgeta i ron bigwan olsem wota. Ol dedbodi blong olgeta bambae i stap roten olbaot long evri ples.”"],[1,18,"Nao profet i talem se, “Long dei ya we Hae God bambae i soemaot kros blong hem, ol silva mo ol gol blong ol man, bambae i no save sevem olgeta. Mo from we ol man oli no ona long Hae God, kros ya blong hem we i olsem faea, bambae i kakae olgeta ples long wol ya. Olgeta man we oli stap long wol ya, bambae oli ded wantaem nomo, we bambae i no gat wan i stap.”","Nao profet i talem se, “Long dei ya we Hae God bambae i soemaot kros blong hem, ol silva mo ol gol blong ol man, bambae i no save sevem olgeta. Mo from we ol man oli no ona long Hae God, kros ya blong hem we i olsem faea, bambae i kakae olgeta ples long wol ya. Olgeta man we oli stap long wol ya, bambae oli ded wantaem nomo, we bambae i no gat wan i stap.”"],[2,1,"Nao Profet Sefanaea i gohed i talem se, “Olgeta. !Yufala i no gat sem nating! Dei ya blong kros blong Hae God bambae i kamtru. Yufala i mas tingting gud fastaem. Sipos no, kros blong hem bambae i kasem yufala olsem we hem i talem, nao bambae yufala i lus, olsem doti we win i karem i go.","Nao Profet Sefanaea i gohed i talem se, “Olgeta. !Yufala i no gat sem nating! Dei ya blong kros blong Hae God bambae i kamtru. Yufala i mas tingting gud fastaem. Sipos no, kros blong hem bambae i kasem yufala olsem we hem i talem, nao bambae yufala i lus, olsem doti we win i karem i go.",2],[2,3,"Yufala long ples ya, we tingting blong yufala i stap daon, mo oltaem yufala i stap obei long ol tok blong Hae God, i gud yufala i stap prea long hem. Yufala i mas mekem ol samting we i stret, mo yufala i mas mekem tingting blong yufala i stap daon long fes blong hem. Sipos yufala i mekem olsem, taem dei blong kros blong hem i kamtru, maet hem i no save givim panis long yufala.”","Yufala long ples ya, we tingting blong yufala i stap daon, mo oltaem yufala i stap obei long ol tok blong Hae God, i gud yufala i stap prea long hem. Yufala i mas mekem ol samting we i stret, mo yufala i mas mekem tingting blong yufala i stap daon long fes blong hem. Sipos yufala i mekem olsem, taem dei blong kros blong hem i kamtru, maet hem i no save givim panis long yufala.”"],[2,4,"Nao profet i talem se, “Taon ya Gasa bambae i finis, i no moa gat man bambae i stap long hem. Mo taon ya Askelon tu bambae i emti, i no moa gat man bambae i stap long hem. Mo ol man blong taon ya Asdod, ol enemi bambae oli ronemaot olgeta long hafdei nomo, mo bambae oli ronemaot ol man Ekron oli gowe long taon ya blong olgeta.","Nao profet i talem se, “Taon ya Gasa bambae i finis, i no moa gat man bambae i stap long hem. Mo taon ya Askelon tu bambae i emti, i no moa gat man bambae i stap long hem. Mo ol man blong taon ya Asdod, ol enemi bambae oli ronemaot olgeta long hafdei nomo, mo bambae oli ronemaot ol man Ekron oli gowe long taon ya blong olgeta."],[2,5,"Ol man Filistia. Yufala i stap klosap long solwota, be sore tumas long yufala. Hae God i jajem yufala finis, se bambae yufala i mas kasem panis. Hem bambae i kilim yufala evriwan i ded, mo bambae i no moa gat wan long yufala i stap.","Ol man Filistia. Yufala i stap klosap long solwota, be sore tumas long yufala. Hae God i jajem yufala finis, se bambae yufala i mas kasem panis. Hem bambae i kilim yufala evriwan i ded, mo bambae i no moa gat wan long yufala i stap."],[2,6,"Ol graon blong yufala klosap long solwota, bambae i kam ples blong sipsip, mo i ples blong man blong lukaot long sipsip, mo i ples blong ol yad blong ol sipsip.","Ol graon blong yufala klosap long solwota, bambae i kam ples blong sipsip, mo i ples blong man blong lukaot long sipsip, mo i ples blong ol yad blong ol sipsip."],[2,7,"Be haf blong ol man Juda* we oli no ded, olgeta ya nao bambae oli holem ol graon blong yufala, mo bambae oli stap lukaot long ol sipsip blong olgeta long hem, mo oli stap slip long ol haos long Askelon. Hae God i God blong olgeta, mo bambae hem i stap wetem olgeta, mo i mekem olgeta oli kam gud bakegen.”","Be haf blong ol man Juda* we oli no ded, olgeta ya nao bambae oli holem ol graon blong yufala, mo bambae oli stap lukaot long ol sipsip blong olgeta long hem, mo oli stap slip long ol haos long Askelon. Hae God i God blong olgeta, mo bambae hem i stap wetem olgeta, mo i mekem olgeta oli kam gud bakegen.”"],[2,8,"Mo profet i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol laen* blong Isrel.* Yufala i man blong mi, mo mi harem finis we ol man Moab mo ol man Amon oli stap tok nogud long yufala, mo oli stap jikim yufala. Oli stap tok flas se bambae oli tekemaot graon blong yufala.","Mo profet i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol laen* blong Isrel.* Yufala i man blong mi, mo mi harem finis we ol man Moab mo ol man Amon oli stap tok nogud long yufala, mo oli stap jikim yufala. Oli stap tok flas se bambae oli tekemaot graon blong yufala."],[2,9,"Mi mi God blong yufala, mo mi laef, mi stap we mi stap. Mo naoia mi promes* long nem blong mi, se mi bambae mi spolem tufala kantri ya Moab mo Amon long sem fasin we mi mi bin spolem Sodom mo Gomora bifo. Tufala kantri ya bambae i kam ples blong sol nomo we bambae i no gat wan gudfala samting i save gru long hem. Ol rabis gras nomo bambae i kavremap tufala, mo bambae tufala i stap nogud olwe gogo i no save kam gud bakegen samtaem. Be yufala we bambae yufala i no ded long ol trabol ya, bambae yufala i go tektekemaot olting blong olgeta ya i blong yufala, mo bambae yufala i holem graon blong olgeta tu.’ ”","Mi mi God blong yufala, mo mi laef, mi stap we mi stap. Mo naoia mi promes* long nem blong mi, se mi bambae mi spolem tufala kantri ya Moab mo Amon long sem fasin we mi mi bin spolem Sodom mo Gomora bifo. Tufala kantri ya bambae i kam ples blong sol nomo we bambae i no gat wan gudfala samting i save gru long hem. Ol rabis gras nomo bambae i kavremap tufala, mo bambae tufala i stap nogud olwe gogo i no save kam gud bakegen samtaem. Be yufala we bambae yufala i no ded long ol trabol ya, bambae yufala i go tektekemaot olting blong olgeta ya i blong yufala, mo bambae yufala i holem graon blong olgeta tu.’ ”"],[2,10,"Nao profet i talem se, “Ol man Moab mo ol man Amon bambae oli kasem panis olsemia nao. Bambae oli kasem panis ya from we oli praod, mo oli stap mekem hed tumas. Hae God i gat olgeta paoa, be oltaem olgeta ya oli stap tok nogud agens long yumi ol man blong hem.","Nao profet i talem se, “Ol man Moab mo ol man Amon bambae oli kasem panis olsemia nao. Bambae oli kasem panis ya from we oli praod, mo oli stap mekem hed tumas. Hae God i gat olgeta paoa, be oltaem olgeta ya oli stap tok nogud agens long yumi ol man blong hem."],[2,11,"Hem bambae i mekem olgeta oli fraet we i fraet. Olgeta god blong wol ya, bambae hem i mekem olgeta i kam olsem nating nomo. Nao ol man blong olgeta kantri bambae oli stap mekem wosip long hem nomo, long weples we oli stap long hem.","Hem bambae i mekem olgeta oli fraet we i fraet. Olgeta god blong wol ya, bambae hem i mekem olgeta i kam olsem nating nomo. Nao ol man blong olgeta kantri bambae oli stap mekem wosip long hem nomo, long weples we oli stap long hem."],[2,12,"“Ol man blong kantri ya Itiopia tu, Hae God bambae i kilim olgeta evriwan i ded.","“Ol man blong kantri ya Itiopia tu, Hae God bambae i kilim olgeta evriwan i ded."],[2,13,"“Hae God bambae i yusum paoa blong hem blong spolem kantri ya Asiria, mo bambae hem i mekem Nineve, bigfala taon ya blong olgeta, i kam nogud olgeta, we bambae i no moa gat man i stap long hem, mo bambae i kam wan draeples we i no gat wota long hem.","“Hae God bambae i yusum paoa blong hem blong spolem kantri ya Asiria, mo bambae hem i mekem Nineve, bigfala taon ya blong olgeta, i kam nogud olgeta, we bambae i no moa gat man i stap long hem, mo bambae i kam wan draeples we i no gat wota long hem."],[2,14,"Ples ya, bambae i kam ples we ol sipsip, mo ol buluk, mo ol narafala wael anamol bambae oli go stap spel long hem. Ol hoknaet bambae oli stap slip olbaot long ol ololfala haos long ples ya we oli brobrok finis. Mo bambae oli stap sidaon long ol windo, nao oli stap singaot. Ol pijin ya reven,* bambae oli stap sidaon long ol step blong ol haos ya, oli stap krae. Ol pos blong ol haos ya we oli katem long ol gudgudfala tri ya sida,* bambae ol man oli tekemaot olgeta evriwan.","Ples ya, bambae i kam ples we ol sipsip, mo ol buluk, mo ol narafala wael anamol bambae oli go stap spel long hem. Ol hoknaet bambae oli stap slip olbaot long ol ololfala haos long ples ya we oli brobrok finis. Mo bambae oli stap sidaon long ol windo, nao oli stap singaot. Ol pijin ya reven,* bambae oli stap sidaon long ol step blong ol haos ya, oli stap krae. Ol pos blong ol haos ya we oli katem long ol gudgudfala tri ya sida,* bambae ol man oli tekemaot olgeta evriwan."],[2,15,"Ol samting ya nao bambae i kasem taon ya, we ol man blong hem oli stap praod tumas long paoa blong olgeta, mo oli stap ting se oli stap gud nomo, oli sef. Ol man blong hem oli stap tok flas se taon blong olgeta i nambawan, i winim ol narafala taon long wol ya. Be naoia, taon ya bambae i kam nogud olgeta, bambae i kam ples blong spel blong ol wael anamol nomo. Ol man we oli stap pas long ples ya, bambae oli sek, oli fraet tumas long hem.”","Ol samting ya nao bambae i kasem taon ya, we ol man blong hem oli stap praod tumas long paoa blong olgeta, mo oli stap ting se oli stap gud nomo, oli sef. Ol man blong hem oli stap tok flas se taon blong olgeta i nambawan, i winim ol narafala taon long wol ya. Be naoia, taon ya bambae i kam nogud olgeta, bambae i kam ples blong spel blong ol wael anamol nomo. Ol man we oli stap pas long ples ya, bambae oli sek, oli fraet tumas long hem.”"],[3,1,"Nao Profet Sefanaea i talem se, “Ol man Jerusalem.* !Sore tumas long yufala! Fasin blong yufala i nogud olgeta. Oltaem yufala i stap girap agens long Hae God, mo yufala i stap mekem i strong tumas long ol man ples blong yufala.","Nao Profet Sefanaea i talem se, “Ol man Jerusalem.* !Sore tumas long yufala! Fasin blong yufala i nogud olgeta. Oltaem yufala i stap girap agens long Hae God, mo yufala i stap mekem i strong tumas long ol man ples blong yufala."],[3,2,"Yufala i no save lesin nating long Hae God, mo taem hem i tok long yufala blong stretem yufala, be yufala i no save harem hem nating. Yufala i no save trastem hem, mo yufala i no save kam long hem blong i givhan long yufala.","Yufala i no save lesin nating long Hae God, mo taem hem i tok long yufala blong stretem yufala, be yufala i no save harem hem nating. Yufala i no save trastem hem, mo yufala i no save kam long hem blong i givhan long yufala."],[3,3,"Ol haeman blong taon ya, oli olsem laeon we i hanggri i stap singaot bigwan. Mo ol man blong jajem man, oli olsem wael dog we i hanggri tumas. Taem hem i kakae wan samting, be i no save livim haf i stap go kasem long moning.","Ol haeman blong taon ya, oli olsem laeon we i hanggri i stap singaot bigwan. Mo ol man blong jajem man, oli olsem wael dog we i hanggri tumas. Taem hem i kakae wan samting, be i no save livim haf i stap go kasem long moning."],[3,4,"Ol profet, ol wok blong olgeta i olbaot nomo, man i no save trastem olgeta, mo ol pris* oli stap mekem ol samting we i tabu, i kam doti long fes blong Hae God, mo oli stap tanem Loa* blong hem blong i folem tingting blong olgeta, blong oli save win long hem.","Ol profet, ol wok blong olgeta i olbaot nomo, man i no save trastem olgeta, mo ol pris* oli stap mekem ol samting we i tabu, i kam doti long fes blong Hae God, mo oli stap tanem Loa* blong hem blong i folem tingting blong olgeta, blong oli save win long hem."],[3,5,"Nating we olgeta ya oli stap mekem olsem, be Hae God i stap oltaem long taon ya. Oltaem, fasin blong hem i stret olgeta, neva hem i mekem samting we i no stret. Evri moning, hem i stap soemaot stret fasin blong hem long ol man blong hem, we i no save mestem. Nating we hem i stap mekem olsem long olgeta, be ol man we fasin blong olgeta i no stret, oli no gat sem nating, oltaem nomo oli stap mekem i nogud.”","Nating we olgeta ya oli stap mekem olsem, be Hae God i stap oltaem long taon ya. Oltaem, fasin blong hem i stret olgeta, neva hem i mekem samting we i no stret. Evri moning, hem i stap soemaot stret fasin blong hem long ol man blong hem, we i no save mestem. Nating we hem i stap mekem olsem long olgeta, be ol man we fasin blong olgeta i no stret, oli no gat sem nating, oltaem nomo oli stap mekem i nogud.”"],[3,6,"Nao profet i gohed i talemaot we Hae God i talem se, “Ol man blong mi. I gat plante kantri we mi mi bin kilim ol man blong olgeta finis. Ol taon blong olgeta, wetem ol stonwol blong ol taon ya, mo ol wajhaos* blong olgeta, mi spolem olgeta evriwan finis. Ol taon ya oli stap nating, mo bigrod blong olgeta oli emti, i no moa gat man blong i wokbaot long olgeta.","Nao profet i gohed i talemaot we Hae God i talem se, “Ol man blong mi. I gat plante kantri we mi mi bin kilim ol man blong olgeta finis. Ol taon blong olgeta, wetem ol stonwol blong ol taon ya, mo ol wajhaos* blong olgeta, mi spolem olgeta evriwan finis. Ol taon ya oli stap nating, mo bigrod blong olgeta oli emti, i no moa gat man blong i wokbaot long olgeta."],[3,7,"Mi mi ting se taem yufala i luk ol samting ya we mi mi mekem, bambae yufala i save ona long mi, mo yufala i save harem ol tok we mi talem long yufala blong stretem yufala, mo yufala i save stap tingbaot ol tok ya, we mi mi bin tijim yufala long hem. Be yufala i girap, yufala i agens long mi olsem bifo.","Mi mi ting se taem yufala i luk ol samting ya we mi mi mekem, bambae yufala i save ona long mi, mo yufala i save harem ol tok we mi talem long yufala blong stretem yufala, mo yufala i save stap tingbaot ol tok ya, we mi mi bin tijim yufala long hem. Be yufala i girap, yufala i agens long mi olsem bifo."],[3,8,"“!Yufala i lukaot! Dei ya blong mi i stap kam we mi bambae mi talemaot we olgeta kantri oli mas kasem panis. Mi mi tingbaot finis blong tekem ol man blong olgeta kantri wetem ol king blong olgeta oli kam wanples, nao bambae oli haremsave paoa blong kros blong mi. Olgeta ples long wol ya, bambae mi spolem olgeta evriwan long paoa blong kros blong mi, we bambae i laet olsem faea.”","“!Yufala i lukaot! Dei ya blong mi i stap kam we mi bambae mi talemaot we olgeta kantri oli mas kasem panis. Mi mi tingbaot finis blong tekem ol man blong olgeta kantri wetem ol king blong olgeta oli kam wanples, nao bambae oli haremsave paoa blong kros blong mi. Olgeta ples long wol ya, bambae mi spolem olgeta evriwan long paoa blong kros blong mi, we bambae i laet olsem faea.”"],[3,9,"Mo bakegen, Profet Sefanaea i talemaot we Hae God i talem se, “Nao biaen long ol samting ya, mi bambae mi jenisim tingting blong ol man blong olgeta kantri, nao bambae oli stap prea long mi nomo. Bambae oli no moa save prea long ol narafala god, bambae oli stap obei long mi nomo.","Mo bakegen, Profet Sefanaea i talemaot we Hae God i talem se, “Nao biaen long ol samting ya, mi bambae mi jenisim tingting blong ol man blong olgeta kantri, nao bambae oli stap prea long mi nomo. Bambae oli no moa save prea long ol narafala god, bambae oli stap obei long mi nomo."],[3,10,"Ol man blong mi we oli stap olbaot long kantri ya Itiopia we i longwe tumas, bambae oli kam, oli givim presen long mi.","Ol man blong mi we oli stap olbaot long kantri ya Itiopia we i longwe tumas, bambae oli kam, oli givim presen long mi."],[3,11,"Mo yufala ol man blong mi, long taem ya, bambae yufala i no moa save sem from fasin ya we fastaem yufala i girap, yufala i agens long mi. Olgeta we oli praod, mo oli stap mekem hed, bambae mi tekemaot olgeta evriwan, nao bambae yufala i no moa save girap agens long mi bakegen long tabu hil* blong mi.","Mo yufala ol man blong mi, long taem ya, bambae yufala i no moa save sem from fasin ya we fastaem yufala i girap, yufala i agens long mi. Olgeta we oli praod, mo oli stap mekem hed, bambae mi tekemaot olgeta evriwan, nao bambae yufala i no moa save girap agens long mi bakegen long tabu hil* blong mi."],[3,12,"Be yufala we tingting blong yufala i stap daon, bambae mi letem yufala nomo i stap long ples ya, nao bambae yufala i stap kam long mi blong mi givhan long yufala.","Be yufala we tingting blong yufala i stap daon, bambae mi letem yufala nomo i stap long ples ya, nao bambae yufala i stap kam long mi blong mi givhan long yufala."],[3,13,"Yufala ol laen* blong Isrel* we bambae yufala i laef i stap, bambae yufala i no moa save mekem i nogud long narafala man, mo bambae yufala i no moa save talem ol giaman toktok, mo yufala i no moa save giaman long man blong trikim hem. Bambae yufala i no moa save sot long wan samting, bambae yufala i stap gud, i no gat wan samting i save spolem yufala. Mo bambae i no moa gat man blong mekem yufala i fraet.”","Yufala ol laen* blong Isrel* we bambae yufala i laef i stap, bambae yufala i no moa save mekem i nogud long narafala man, mo bambae yufala i no moa save talem ol giaman toktok, mo yufala i no moa save giaman long man blong trikim hem. Bambae yufala i no moa save sot long wan samting, bambae yufala i stap gud, i no gat wan samting i save spolem yufala. Mo bambae i no moa gat man blong mekem yufala i fraet.”"],[3,14,"Nao Profet Sefanaea i talem se, “Ol laen* blong Isrel.* Yufala i mas glad, yufala i singsingaot. Ol man Jerusalem.* Yufala i mas harem gud long olgeta tingting blong yufala.","Nao Profet Sefanaea i talem se, “Ol laen* blong Isrel.* Yufala i mas glad, yufala i singsingaot. Ol man Jerusalem.* Yufala i mas harem gud long olgeta tingting blong yufala."],[3,15,"Naoia panis blong yufala i finis, Hae God i no moa save panisim yufala. Hem i tekemaot ol enemi blong yufala finis. Hem i King blong yufala, mo naoia hem i stap wetem yufala, mo i no moa gat wan samting blong yufala i fraet long hem.","Naoia panis blong yufala i finis, Hae God i no moa save panisim yufala. Hem i tekemaot ol enemi blong yufala finis. Hem i King blong yufala, mo naoia hem i stap wetem yufala, mo i no moa gat wan samting blong yufala i fraet long hem."],[3,16,"I gat taem i stap kam we bambae ol man oli talem long ol man Jerusalem se, ‘Ol man Saeon.* Yufala i no fraet, yufala i no letem han blong yufala i stap hang blong soemaot se yufala i stap harem nogud.","I gat taem i stap kam we bambae ol man oli talem long ol man Jerusalem se, ‘Ol man Saeon.* Yufala i no fraet, yufala i no letem han blong yufala i stap hang blong soemaot se yufala i stap harem nogud."],[3,17,"Hae God i God blong yufala, mo hem i stap wetem yufala. Paoa blong hem i stap mekem yufala i win. Hem bambae i glad long yufala. Fasin blong hem we oltaem hem i stap lavem man, bambae i mekem yufala i gat niufala laef. Hem bambae i glad tumas long yufala we bambae i stap singsing from.","Hae God i God blong yufala, mo hem i stap wetem yufala. Paoa blong hem i stap mekem yufala i win. Hem bambae i glad long yufala. Fasin blong hem we oltaem hem i stap lavem man, bambae i mekem yufala i gat niufala laef. Hem bambae i glad tumas long yufala we bambae i stap singsing from."],[3,18,"Hem bambae i glad tumas, olsem ol man we oli stap mekem lafet.’ ” Mo profet i talemaot we Hae God i talem se, “Bigfala trabol ya, mi bambae mi tekemaot, mo bambae mi mekem we yufala i no moa sem.","Hem bambae i glad tumas, olsem ol man we oli stap mekem lafet.’ ” Mo profet i talemaot we Hae God i talem se, “Bigfala trabol ya, mi bambae mi tekemaot, mo bambae mi mekem we yufala i no moa sem."],[3,19,"I gat taem i stap kam we bambae mi mi givim panis long olgeta we oli stap mekem i strong tumas long yufala. Olgeta ya we oli no save wokbaot gud bambae mi sevem olgeta, mo olgeta we oli stap wok slef* long narafala kantri mi bambae mi tekem olgeta evriwan i kambak long stret ples blong olgeta. Olgeta ya we oli stap sem, bambae mi tekemaot sem long olgeta, mi mekem ol man oli ona gud long olgeta, mo olgeta man long wol ya bambae oli stap presem olgeta.","I gat taem i stap kam we bambae mi mi givim panis long olgeta we oli stap mekem i strong tumas long yufala. Olgeta ya we oli no save wokbaot gud bambae mi sevem olgeta, mo olgeta we oli stap wok slef* long narafala kantri mi bambae mi tekem olgeta evriwan i kambak long stret ples blong olgeta. Olgeta ya we oli stap sem, bambae mi tekemaot sem long olgeta, mi mekem ol man oli ona gud long olgeta, mo olgeta man long wol ya bambae oli stap presem olgeta."],[3,20,"Ol man Jerusalem. I gat taem i stap kam, we ol man ples blong yufala we oli stap olbaot long evri ples, bambae mi tekem olgeta i kambak long stret ples blong yufala bakegen. Bambae mi mekem nius blong hae nem blong yufala i kasem olgeta ples long wol ya, mo bambae mi mekem yufala i kam rijman bakegen. Mi mi Hae God, mo hemia tok blong mi.”","Ol man Jerusalem. I gat taem i stap kam, we ol man ples blong yufala we oli stap olbaot long evri ples, bambae mi tekem olgeta i kambak long stret ples blong yufala bakegen. Bambae mi mekem nius blong hae nem blong yufala i kasem olgeta ples long wol ya, mo bambae mi mekem yufala i kam rijman bakegen. Mi mi Hae God, mo hemia tok blong mi.”"]]}};